INSERT INTO rag_documents (id, title, content, tags, status, source, sort, update_time)
VALUES
(100001, '英雄之旅总览：把生命当作创造与疗愈的冒险', '英雄之旅不是追逐名利的个人奋斗剧本，而是一种把生命视为伟大冒险的意识训练：人被某种更深的力量触碰，离开惯性的生活方式，经历失联、磨难、失败、整合与疗愈，最后带着获得的礼物回到世界，贡献给他人。课程正文把这一主线放在当代处境中理解：人很容易陷入负面念头、焦虑、抑郁、过度分析和小我身份，因而失去与生命力、创造力、身体和世界的连接。所谓正能量人生，并不是永远顺利，而是能全身心参与生命，在困难中保持开放，把痛苦转化为更完整的人性。整个十二模块可视为一条路径：听见召唤，看见拒绝，找到向导，训练创造性心智，连接资源，召回温柔、勇猛、顽皮等原型能量，把障碍和恶魔转化为资源，再把礼物传给他人。英雄之旅的核心价值，是让个人从孤立的小我走向身心灵整合，再走向社群与世界的疗愈；每个人都携带一份独特礼物，旅程的意义在于听见它、训练自己承载它、并把它分享出去。它不是一次顿悟，也不是外部成就清单，而是持续的身心练习：安顿、呼吸、放下固化形式，重新选择如何回应生命。用于问答检索时，可对应生命意义、创造力低落、人生卡住、痛苦转化、如何贡献社会等问题。', '["英雄之旅", "创造力", "疗愈整合", "正能量人生", "生命礼物", "社群贡献"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 10, now()),
(100002, '聆听召唤：从童年火光到一生价值的辨认', '召唤不是头脑临时想出的目标，而是生命中反复触碰你的深层信号。它可能来自童年第一次被某个人、一本书、一首音乐、一个科学家或艺术家点亮的瞬间，也可能来自一次巨大的痛苦之后的重生，或来自想象临终回望时会让自己说出此生值得的价值。课程强调，人常被左脑的过度分析锁住，越努力想答案，越难听见召唤；所以练习不是思考清单，而是先安顿身体、呼吸、向天空伸展、向大地释放，再把问题像种子一样投入全身心，让画面、记忆和感受自然浮现。可反复询问：小时候谁启发了我，哪次挣扎让我更有生命力，哪个艺术作品打开过我，若生命将尽我希望完成什么。召唤常常短暂，却不会消失；它像内在已经存在的火，提醒你什么能让生命鲜活、快乐、神奇，也提醒你如何成为更好的自己并帮助别人。当出现多个答案时，不必急着选择哪一个正确，而是观察哪个让身体更放松、更有热、更多泪水或敬畏；这些生理反应常比逻辑判断更接近召唤。', '["召唤", "童年记忆", "生命使命", "身心练习", "价值澄清", "创造力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 20, now()),
(100003, '拒绝召唤与找到向导：把“不可能”转化为支持', '当一个人感到自己想创造某种生命、事业或关系时，拒绝召唤几乎会同步出现。它可能是父母、家庭、社会、性别角色、职业规划或内在批评者的声音，反复说你不能、你不该、那不现实。课程没有把这部分视为错误，而把它看成英雄之旅必经的张力：心中的渴望和头脑中的限制讯息同时存在，真正的成熟不是假装没有阻力，而是能与阻力同场工作。练习的关键，是先触碰心，说出我最想创造的是什么，并让身体做出代表梦想的动作；再走到另一边，进入批评者角色，用姿态和声音表达不允许，重复几次直到能看见它的能量模式；最后请出导师、祖先、榜样或灵性向导，走进他们的身体、眼神和神态，接收支持与许可。向导可以是现实老师、亲人、已故长辈、文学人物或内在智慧。这样做不是否认批评，而是让支持系统比批评更有能量，使人能在真实世界中带着勇气迈步。', '["拒绝召唤", "内在批评", "向导", "导师资源", "身体模型", "自我支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 30, now()),
(100004, '创造性心智：用游戏、幽默和多重视角重新连接生命', '创造性心智的核心是不被单一视角锁住。课程把右脑比作开放的海洋，能把任何事物连接到其他事物；左脑则像语言电脑，擅长代表、分析和控制，但如果成为唯一中心，就会让人困在机器世界，失去心灵、身体和奥秘感。创造性的人会移动、发散、玩耍、幽默，并能像孩子一样流动，同时保有成人的成熟。练习上，可以一天多次收回注意力、触碰心、打开全身通道，暂时放下固定身份，感受自己既是孩子、成年人、古老的生命、大树、动物，也是宇宙的一部分。通过身体动作、声音、笑和想象，人的小我身份会松动，生命意图便能从更广阔的创造意识中表达出来。这种玩耍不是逃避现实，而是让心智恢复灵活性。若发现自己僵硬、无趣、只能想出一种做法，正是需要进入创造性心智的信号。', '["创造性心智", "右脑连接", "左脑分析", "游戏精神", "多重身份", "身体觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 40, now()),
(100005, '三种心智与正念种子：静止、寂静、无边无际', '课程把更深的正念状态分为语言心智、身体心智和场域心智。语言心智容易担忧、解释和计划；身体心智若被紧绷占据，就会阻塞生命之气；场域心智则指人与家庭、城市、自然、社群及万有生命的连接。仅在头脑里设定目标，往往缺少直觉、自信和流动，因此需要把意图放入更精微的身心场域中。三颗种子的练习分别对应三个层面：把静止投入身体，让肌肉和姿态慢下来，像大树向下扎根又向天空打开；把寂静投入语言心智，让杂念在宽阔空间中休息，而不是用力驱赶；把无边无际投入场域心智，让涟漪从心和腹部扩散到周围一切人事物。等身体像光、头脑有寂静、场域能包容时，再说出我想在世界上创造的是什么，创造力会比紧张努力更稳定。', '["三种心智", "正念种子", "语言心智", "身体心智", "场域心智", "生命之气"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 50, now()),
(100006, '三个正向连接：意图、中心与资源圆环', '真正把召唤带到世界，不只是想清楚目标，而是同时建立三个正向连接。第一是简洁、正向、有共振的意图，例如我最想创造的是某种关系、疗愈、平静或贡献；第二是身体中心，可能在心口、腹部或其他最有能量感的地方，当压力、未知、速度过快或注意力涣散时，回到中心就等于回到根基；第三是资源圆环，包含导师、朋友、家人、自然地点、动物、祖先、灵性存有、社群或任何能支持你走路的人事物。练习时先安顿，下沉并打开；再看见未来时间线，一步步前进，每一步都重新感受意图、中心和资源。资源不是抽象安慰，而是一个可被身体感到的场：有人看见你、爱你、理解你、支持你继续。三连可作为任何计划前的微流程：先说清意图，再摸到中心，最后看见资源；三者同时在线时，行动更有弹性和耐力。', '["资源连接", "正向意图", "身体中心", "资源圆环", "时间线", "社群支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 60, now()),
(100007, '三种原型能量：温柔、勇猛与顽皮的整合', '为了让召唤能在沟通和行动中实现，课程提出三种普世原型能量：温柔、勇猛、顽皮。温柔让人先对自己良善，也能在紧张的人际氛围中建立信任和安全；但只有温柔会失去边界，所以需要勇猛的专注、火焰、决心和复原力。勇猛若脱离心灵，会变成暴力、批评或霸凌，因此必须回到人性的中心。顽皮则让人从过度严肃和僵硬中解放出来，带来笑、轻盈、好奇和创造性沟通。练习方式是为每种能量找到代表人物或榜样，进入他们的身体、眼神和姿态，再回到自己身上，用这股能量表达同一个生命意图。成熟表达是三者同时服务于心灵，而不是各自失控。冲突中若只有温柔，容易退让；只有勇猛，容易压迫；只有顽皮，容易逃避深度。', '["原型能量", "温柔", "勇猛", "顽皮", "沟通", "创造力训练"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 70, now()),
(100008, '用原型能量面对障碍：合气道式地欢迎与引导', '障碍在英雄之旅中被称为恶魔，可能是内在恐惧、批评、失联、羞耻，也可能是外在家人、机构、工作环境或不支持你的人。课程借用艾瑞克森取向和合气道精神：不要与阻碍硬碰硬，不要暴力消灭、逃离或控制，而是先与它相合，欢迎它，再把关系带向更好的方向。练习时先站在意图和中心里，看见未来道路，再让一个具体障碍出现在前方。用正向勇猛面对它时，感受边界、眼神、站立方式和可以说出的清晰话语；用顽皮面对它时，跳舞、转圈、笑，避免把力量交给障碍；用温柔面对它时，先支持自己的脆弱，再以成熟善意触碰阻碍背后的痛苦。障碍不是旅程失败的证据，而是提醒你回到中心并调用更完整的自己。', '["障碍转化", "恶魔", "合气道", "非暴力", "边界", "原型应用"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 80, now()),
(100009, '转化恶魔：从问题行为里识别正向需求', '问题、症状和成瘾行为表面上像敌人，深处常隐藏着尚未被看见的正向需求。课程用恶龙可能是等待被发现的礼物来说明这一点：如果只分析、压制、逃避或攻击问题，就会切断它携带的资源。更有效的方法是发展身体模型。选择一个反复让你挣扎的行为或情绪，例如焦虑、缺乏安全感、拖延、上瘾；不要急着解释，不要命令它停止，而是让身体自然做出一个姿态或重复动作，并以比平常慢数倍的节奏、温柔和好奇来体验它。然后在动作中询问：这个模式想为我创造什么，它想满足哪种正向需求。关键在于区分需求和策略：需求可能是安全、温暖、休息、连接或自由，旧策略可以被替换，但需求必须被尊重。', '["恶魔转化", "身体模型", "正向需求", "症状意义", "艾瑞克森", "成瘾疗愈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 90, now()),
(100010, '目标与障碍整合：让对立面成为同一支舞', '目标和障碍并不总是敌对关系，很多症状其实在尝试恢复平衡。一个人用紧绷、强硬和肌肉力量逼自己完成项目，结果拖延不断出现；拖延看似恶魔，深处却可能代表放松、休息、释放和阴性能量，提醒他不能只靠蛮力。整合练习先为目标建立身体模型，感受我真正想创造的是什么；再为每当我想创造它时被触发的那一面建立身体模型，如抑郁、自我批判、恐惧、愤怒或拖延。不要用对错评判两边，而是用缓慢、温柔、顽皮、好奇的动作欢迎每一面，倾听它各自代表的正向需求。整合后的行动不是折中妥协，而是让目标获得障碍所携带的智慧：努力获得休息，勇气获得柔软，前进获得节奏，因此更能长期持续。', '["目标整合", "障碍整合", "阴阳平衡", "拖延", "身体舞蹈", "创造性完整"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 100, now()),
(100011, '传递给他人：把获得的礼物变成世界的光', '英雄之旅最终不是把天分囤积起来，而是传递给他人。课程通过艾瑞克森对学生的教导指出，真正的回报方式是把有用的东西继续分享。一个人在年轻时需要专注自己的目标，但当能力和成功逐渐出现，如果只追逐名利、金钱和外在认可，创造力会再次收缩；若把天赋视为被托付的礼物，并用来帮助别人，生命会更快乐、更宽广。练习上，先放下比较、表演和赚钱的压力，进入让自己感到神圣、平静、合一的空间，感受内在不可摧毁的光。分享不是拯救姿态，也不是牺牲自我，而是让自己的觉醒映照并唤醒他人的觉醒。真正分享时必须先保持自己的光，不在关系中耗尽自己，而是从充满的中心去照亮。', '["传递给他人", "贡献", "礼物", "艾瑞克森", "慈悲练习", "社群疗愈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 110, now()),
(100012, '回顾整合：把每一天活成完整的英雄之旅', '最后的整合练习把十二个模块收束为日常道路：先安顿、下沉大地、向天空打开，让语言像音乐和梦一样流入全身；记得自己来到世界是为了给出一份礼物，也诚实看见曾经因为不被支持而转身拒绝。然后寻找榜样、向导和能让灵魂相触的人，学习把觉知中心从头脑转回身体、心灵和场域。日常行动中，要保留玩耍、温柔、勇猛、专注和严肃的混合状态；遇到障碍时，退后一步成为大树，回到静止、寂静和无边无际，再用身体模型、合气道式欢迎和创造性好奇把冲突转为合作。英雄之旅不是一次性完成的课程，而是每一天都能重新选择的活法：过好今天，享受这一刻，并支持他人也活出他们的旅程。', '["回顾整合", "每日练习", "感恩", "宽恕", "宇宙连接", "享受生命"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 120, now()),
(100013, '1号完美型：核心识别与成长建议', '1号的核心不是简单的爱挑剔，而是内在长期有一套高标准在审判：这件事对不对、够不够好、还能不能改进。他们把责任、秩序、原则和正确性放在快乐之前，擅长发现漏洞、维护规范、把事情做扎实。盲点是把应该当成唯一道路，把错误看成道德问题，把愤怒压成不满、讽刺、僵硬的礼貌或反复纠错。成长关键是从内在批评家退后一步，区分我想要和我应该，允许错误、风险和多种答案存在；把事实核对代替脑内定罪，把感谢与肯定说出口；给日程留白，练习享受、求助和适度妥协；把怒气视为被忽略需求的信号，用清楚、非控诉的语言表达边界。成熟的1号会把高标准转化为可靠、正直和持续改善，而不是让自己和他人永远不合格。', '["九型人格", "1号", "完美型", "完美主义者", "内在批评", "愤怒", "原则", "成长建议"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 210, now()),
(100014, '2号助人型：核心识别与成长建议', '2号的核心驱动力是通过被需要、被喜欢、被认可来确认自己的价值。他们能快速捕捉他人的情绪和需求，愿意支持、照顾、连接资源，也善于让别人感觉自己很重要。盲点是注意力长期放在他人身上，自己的真实需要会变得模糊，付出容易夹带期待：我这么懂你、帮你，你是否也会爱我、重视我？得不到回应时，2号可能受伤、抱怨、控制、吃醋。成长建议是停止用过度付出来换取关系安全，帮助前先问：这是对方真正需要，还是我想证明自己重要？把隐性期待改成直接请求，允许自己接受照顾；建立边界，不把拒绝理解为不爱。成熟的2号能温暖地滋养他人，也能诚实承认自己的欲望、脆弱和限度。', '["九型人格", "2号", "助人型", "给予者", "被需要", "认可", "边界", "关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 220, now()),
(100015, '3号成就型：核心识别与成长建议', '3号的核心关注是成功、效率、形象和可见成果：我怎样被尊敬、被认可、被证明有价值。他们行动快、目标感强、能读懂场域并切换角色，适合推动项目、包装想法、销售愿景、鼓舞团队。代价是把正在做什么误当成我是谁，把悲伤、恐惧、疲惫和亲密需求视为影响表现的干扰。成长方向是从表演自我回到诚实自我：定期停下问自己喜欢什么、不喜欢什么、身体感觉如何；把休息和情感觉察也放进日程，而非只安排产出；学习承认失败、困惑和普通时刻，不急着换项目或换形象。成熟的3号依然高效有感染力，但其价值不再完全依赖掌声。', '["九型人格", "3号", "成就型", "实干者", "形象", "成功", "工作狂", "诚实"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 230, now()),
(100016, '4号自我型：核心识别与成长建议', '4号的核心经验是强烈地感到我与别人不同，并在失落、渴望、独特性和真实表达中寻找自我。他们情感细腻，能进入他人的痛苦，富有审美、创造力和意义感。盲点是注意力容易停在缺失处：现实有什么不够，别人拥有什么而我没有，理想关系为何迟迟不到；情绪会被当成身份，嫉妒、忧郁、浪漫化和戏剧性表达会反复出现。成长建议是尊重情感但不被情感定义：把我感觉如此与事实必然如此分开；在普通日常中建立稳定行动；把嫉妒当成愿望线索，转化为可执行选择；亲密关系中直接表达需要，少用疏离、戏剧化或测试来证明爱。', '["九型人格", "4号", "自我型", "悲情浪漫者", "情绪", "嫉妒", "真实", "创造力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 240, now()),
(100017, '5号理智型：核心识别与成长建议', '5号的核心策略是用观察、知识和边界来保护时间、能量与内在空间。他们擅长客观分析、系统研究、保持冷静，常在独处后才重新接触情绪。压力点在于把外界需求体验成侵入，把亲密、承诺或即时回应视为资源消耗，于是退回头脑、分隔生活领域、少说少给；情绪可能不是没有，而是被推迟到安全独处时才浮现。成长建议不是强迫外向，而是让知识与生命重新连接：在尚未准备完美时也小步参与；用简短语言告诉别人自己需要多少时间和空间，而不是消失；练习在当下辨认身体和情绪，别只事后复盘。', '["九型人格", "5号", "理智型", "观察者", "边界", "知识", "抽离", "独处"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 250, now()),
(100018, '6号忠诚型：核心识别与成长建议', '6号的核心注意力在安全、信任、风险和权威：哪里会出问题，谁可靠，我的决定是否稳妥。他们能预演最坏情况，发现隐藏漏洞，对团队和承诺很忠诚。盲点是焦虑会让他们在顺从与挑战权威之间摆动，既想得到保护又担心被控制；他们可能怀疑他人动机、拖延决定、反复确认，或用反恐惧方式冲向危险来证明自己不怕。成长建议是发展内在权威：把事实、想象、直觉和投射分栏记录；为决策设定截止时间，允许足够好而非绝对安全；公开提出疑问，不在背后累积猜测；练习想象正面结果，让身体体验安全。', '["九型人格", "6号", "忠诚型", "怀疑论者", "安全", "信任", "权威", "焦虑"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 260, now()),
(100019, '7号快乐型：核心识别与成长建议', '7号的核心追求是可能性、自由、快乐和未来计划。他们乐观、点子多、反应快，能把不同事物连接成新方案，擅长带来兴奋感、创新气氛和对未来的信心。盲点是害怕被限制、无聊或痛苦困住，容易用新选择、合理化、玩笑和忙碌避开难受感；承诺后仍保留退路，兴趣下降就转向下一个刺激，未完成事项堆积。成长建议是把自由从永远有别的选择升级为能选择并完成：限制同时进行的项目，给承诺设置收尾标准；遇到痛苦时先停留、呼吸、命名感受，不急着转移；评估计划时同时看风险、资源和代价。', '["九型人格", "7号", "快乐型", "享乐主义者", "自由", "乐观", "选择", "逃避痛苦"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 270, now()),
(100020, '8号领袖型：核心识别与成长建议', '8号的核心关注是力量、控制、公正和真实。他们直接、有行动力，能在混乱中接管局面，保护弱者，讨厌虚伪、软弱和被蒙在鼓里。压力点在于把世界分成强者与弱者，隐藏脆弱，用愤怒、强势和报复来恢复控制，可能无意中让他人害怕或沉默。成长建议是把力量从压制转为承担：行动前先听完整信息，尤其欢迎坏消息；区分我在保护与我在控制；练习用较低强度表达需求，给别人反应时间；在可信对象面前承认害怕、在乎或受伤，不把柔软等同于失败；冲突中追求清楚和修复，而不只是胜利。', '["九型人格", "8号", "领袖型", "保护者", "控制", "正义", "愤怒", "脆弱"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 280, now()),
(100021, '9号和平型：核心识别与成长建议', '9号的核心策略是维持和谐、避免冲突，并把自己融入他人的节奏。他们能倾听多方、理解不同立场、提供稳定支持，是天然的调停者。盲点是忘记自己的优先级，把重要愿望让位给琐事、习惯或他人安排，表面顺从内心保留，压力下以拖延、麻木、被动抵抗表达愤怒。成长建议是把和平从没有冲突升级为真实参与：每天写下自己的一个偏好、一个不愿意、一个下一步行动；用期限和结构帮助聚焦，先做最重要的小步骤；练习直接表达不同意见，不用拖延让别人猜；把愤怒视为生命力和边界的信号。', '["九型人格", "9号", "和平型", "调停者", "和谐", "冲突回避", "惯性", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 290, now()),
(100022, '通用机制：注意力焦点、直觉与三大中心', '九型不是先看外在行为，而是看注意力被什么自动吸走。性格一旦形成，人会选择性搜集信息：1号看对错与改进，2号看别人是否需要和喜欢自己，3号看表现能否获得肯定，4号看缺失、独特和真实感，5号看边界与资源要求，6号看风险和隐藏意图，7号看快乐选择与未来可能，8号看失控、不公和力量对比，9号看他人安排与各方立场。身体中心8、9、1常通过腹部和本能感知环境；情感中心2、3、4通过关系、形象和情绪共鸣感知；精神中心5、6、7通过观察、预测和联想感知。成长入口是成为内心观察者：记录自己第一时间注意到什么、忽略什么；区分事实、解释、幻想和直觉。', '["九型人格", "通用机制", "注意力", "直觉", "三大中心", "身体中心", "情感中心", "精神中心"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 310, now()),
(100023, '通用机制：两翼、核心动机与同型差异', '两翼指某个型号相邻两侧型号对其表达方式的影响。它不是另一个核心类型，也不是简单的副人格，而是让同一型号呈现不同气质的调味层：偏5翼的4号可能更内收、理性和孤僻，偏3翼的4号可能更外显、形象化和有舞台感；偏8翼的9号更硬、更能顶住压力，偏1翼的9号更克制、更在意正确与秩序。使用两翼时要避免只凭风格判断，例如一个强势的9号不等于8号，一个外向的5号也不等于7号。先问核心动机：他是在维护和谐、保留资源，还是追求自由？再看两翼怎样改变表达。两翼解释差异，不替代访谈、情境和长期注意力观察。', '["九型人格", "通用机制", "两翼", "核心动机", "同型差异", "识别方法"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 320, now()),
(100024, '通用机制：压力线、安全线与状态变化', '每个型号不是静态标签，而是由日常主型、压力状态、安全状态共同构成。压力状态常沿箭头离开本型：1到4、2到8、3到9、4到2、5到7、6到3、7到1、8到5、9到6；安全状态常沿反向进入：1到7、2到4、3到6、4到1、5到8、6到9、7到5、8到2、9到3。使用时不要把安全线等同于一定健康、压力线等同于一定糟糕；安全也可能暴露阴影，压力也可能激发能力。关键是观察状态变化：在放松、受威胁、被爱、被批评时你变成什么样？成长不是迷恋安全态，而是能觉察三种状态、整合其正面资源，并在负面反应出现前暂停选择。', '["九型人格", "通用机制", "压力线", "安全线", "动态变化", "九角星", "状态识别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 330, now()),
(100025, '通用机制：关系与职场沟通的九型用法', '九型用于关系和职场时，重点不是给人分类，而是找到对方的原动力、焦虑点和沟通入口。1号需要尊重其标准，同时减少你错了的羞辱感；2号需要感谢但也要鼓励其说出真实需求；3号需要目标和认可，也要提醒其关注人和过程；4号需要真实与意义，反馈要避免轻率否定其感受；5号需要提前信息、边界和思考时间；6号需要透明、稳定承诺和可验证依据；7号需要空间与愿景，同时要明确收尾责任；8号需要直说、完整信息和可信赖的边界；9号需要清晰结构、温和追问和表达异议的安全感。成熟用法是用类型翻译彼此语言：把评判译成对质量的在乎，把控制译成对安全的需求，把拖延译成冲突恐惧，再讨论可执行请求。', '["九型人格", "关系", "职场", "沟通", "领导力", "反馈", "冲突", "团队管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 340, now()),
(100026, '关键对话：先恢复安全感，再讨论观点差异', '关键对话通常同时具备三个特征：观点不同、利害关系重大、情绪强烈。很多沟通失败不是因为道理不够，而是对话安全感已经破裂；一旦人感觉被攻击、羞辱或不被尊重，就会转入沉默或暴力：沉默包括回避、掩饰、退出，暴力包括控制、贴标签、攻击和打断。有效处理关键对话的第一步，不是立刻证明自己正确，而是观察气氛是否安全：对方是否还愿意说真话，自己是否还在听。若安全感下降，应先暂停内容争论，说明共同目的和尊重，例如“我不是要否定你，我想一起把问题解决”。然后再陈述事实、表达感受、解释自己的故事、询问对方看法。App 问答可用于伴侣冲突、上下级反馈、客户沟通和团队分歧。', '["关键对话", "沟通", "安全感", "冲突", "反馈", "沉默", "暴力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 410, now()),
(100027, '非暴力沟通四步：观察、感受、需要、请求', '非暴力沟通的核心，是把注意力从评判、指责、命令和辩解，转向人真实的观察、感受、需要和请求。第一步是观察：具体说发生了什么，避免“你总是”“你从来不”等概括性评价。第二步是感受：表达自己身体和情绪的真实状态，如失落、担心、疲惫、安心，而不是伪装成感受的指责。第三步是需要：为自己的感受负责，看到背后未被满足的需要，如尊重、休息、连接、自由、安全、理解。第四步是请求：提出具体、可执行、当下可回应的请求，而不是模糊期待或命令。它并非软弱妥协，而是让双方从敌对意识回到生命需要。适合回答亲密关系争吵、亲子沟通、职场表达、如何提出边界和如何道歉。', '["非暴力沟通", "观察", "感受", "需要", "请求", "同理心", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 420, now()),
(100028, '情绪急救：拒绝、孤独、失败和反刍需要及时处理', '日常心理伤害也需要像身体伤口一样做急救。拒绝会带来尖锐痛感，削弱自尊和归属感；孤独会让人更敏感、更防御，甚至把真正能靠近的人推开；失败容易让人把一次结果扩大成对自我的否定；反刍会让痛苦反复激活，形成焦虑和抑郁倾向。情绪急救的第一原则是尽早处理，而不是硬扛。可以先给情绪命名，承认痛苦真实存在；再把事件与自我价值拆开，避免“我被拒绝=我不值得”；随后做具体修复：联系安全的人、恢复日常行动、减少反复回放、写下可学习之处。若痛苦持续影响睡眠、工作、饮食、现实判断或有自伤风险，应寻求专业帮助。App 可用于被拒绝、失恋、孤独、失败、自卑和内耗等场景。', '["情绪急救", "拒绝", "孤独", "失败", "反刍", "自尊", "心理创伤"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 430, now()),
(100029, '自控力：先观察失控模式，再设计环境', '自控不是靠羞辱自己变强，而是成为自己的观察者，理解何时、何地、因为什么失控。很多人越相信自己意志坚定，越容易把自己暴露在诱惑中；一旦失败，又因为意外和羞耻而放弃。更有效的方法是像科学家一样收集数据：什么时候最容易拖延，什么情绪会触发消费或暴食，哪些人、地点、App 或疲劳状态会削弱自控。然后设计环境而不是只发誓：减少诱惑可见度，提前设定下一步动作，把长期目标和眼前选择连接起来，用小实验测试哪种方法有效。自控力还包含“我要做”“我不要”“我想要”三种力量：不仅要抵制诱惑，也要记得真正重要的目标。App 可用于拖延、成瘾、情绪性消费、减肥、学习和习惯改变。', '["自控力", "意志力", "拖延", "习惯改变", "观察者", "诱惑", "目标"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 440, now()),
(100030, '解决冲突：把冲突当作信息，而不是立即消灭', '冲突不可完全避免，重要的是把它当作信息入口，而不是马上逃跑、压制或赢过对方。高质量冲突处理从理解发生了什么开始：双方各自看到了什么事实，分别受到什么影响，各自真正关心什么。很多人一遇冲突就急着解决，反而没弄清原因；也有人任由敌意升级，错失修复机会。有效做法是先降低攻击性表达，帮助聆听和说话变得容易：少用指责，多用具体事件；少说“你就是”，多问“你当时看到的是什么”；承认对方处境，同时表达自己的边界和请求。冲突的目标不是双方都委屈地妥协，而是找到能照顾重要需要的新路径。App 可用于伴侣冷战、团队矛盾、朋友误会、谈判和家庭分歧。', '["解决冲突", "聆听", "对话", "边界", "关系修复", "谈判", "误会"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 450, now()),
(100031, '创伤反应：身体会记住未完成的危险', '创伤并不只是记忆里的一段故事，也会保存在身体、神经系统和关系反应中。经历过创伤的人可能明知现在安全，却在类似声音、气味、表情、距离或权威情境中突然紧绷、麻木、愤怒、逃离或讨好；这不是矫情，而是身体在用旧系统保护自己。疗愈的核心之一是重新建立安全与调节能力：先识别触发点和身体信号，再用呼吸、地面感、身体移动、稳定关系和可预测环境帮助神经系统回到当下。不要急着逼自己讲完所有创伤细节，身体安全比叙事完整更基础。关系中，创伤者需要被看见、被尊重节奏，而不是被催促“想开点”。App 可用于惊恐、麻木、过度警觉、亲密关系触发和创伤后自我理解。', '["创伤疗愈", "身体记忆", "安全感", "神经系统", "触发点", "情绪调节", "依恋"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 460, now()),
(100032, '回避型模式：逃避情绪会让关系和自我更空', '回避型或逃避型人格模式常见于对拒绝、失望、犯错和暴露脆弱高度敏感的人。为了不被伤害，他们会隐藏不安全感，努力保持理性、独立、无所谓，甚至把真实情绪像流感一样躲开。短期看，逃避能减少痛苦；长期看，它会让人失去与自己和他人的情绪连接，形成空虚、焦虑、亲密困难和自我价值感低落。成长不是一次性冲进情绪，而是安全地接触：当想逃跑、责备或麻木时，先停下，命名身体感受和脑中故事；区分真实事件与旧信念；用小剂量表达需要和脆弱，观察关系是否真的崩塌。App 可用于回避亲密、不敢表达、不安全依恋、内心空虚和情绪逃避。', '["回避型人格", "不安全依恋", "情绪逃避", "亲密关系", "脆弱", "自我价值", "焦虑"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 470, now()),
(100033, '边界表达：清楚说不，不等于伤害关系', '很多关系问题不是缺少爱，而是缺少清楚边界。没有边界的人容易讨好、压抑、拖延、爆发；边界过硬的人则可能控制、隔离、拒绝连接。健康边界是既承认关系重要，也承认自己的时间、身体、情绪和价值同样重要。表达边界时，先具体说明事实和影响，再表达自己的限制和可提供的替代方案，例如“我今晚需要休息，不能继续讨论；明天十点我可以认真听你说”。边界不是惩罚，也不是让对方猜，而是让关系可持续。若对方不适应你的新边界，不代表你错了；这只是关系系统在重新调整。App 可用于不会拒绝、被索取、关系内耗、职场加班、人情压力和亲密关系空间。', '["边界", "拒绝", "讨好", "关系内耗", "自我照顾", "沟通", "亲密关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 480, now()),
(100034, '行动改变：把大目标拆成可重复的小实验', '无论是九型成长、英雄之旅还是自控力训练，真正改变都需要从宏大愿望落到小实验。大目标容易激发热情，也容易引发压力、完美主义和拖延；小实验则让人用数据学习，而不是用自责消耗。设计实验时要明确：我要观察什么，下一步最小行动是什么，何时做，做完如何记录。比如想改善沟通，不是发誓以后不吵架，而是每次冲突前先说一个事实、一个感受、一个请求；想减少拖延，不是要求自己从此自律，而是先开始5分钟并记录触发点。失败不是人格失败，而是实验数据，提醒你调整环境、节奏、支持或目标。App 可用于习惯养成、学习计划、关系修复、情绪管理和职业目标推进。', '["行动改变", "小实验", "习惯养成", "拖延", "目标拆解", "复盘", "成长练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 490, now()),
(100035, '关系修复：先承认影响，再解释动机', '关系受伤后，很多人急着解释自己不是故意的，却忽略对方已经受到影响。修复对话应先承认事实和影响：我看到我刚才打断你，让你觉得不被尊重；再表达自己的感受和需要；最后提出可执行的修复请求或承诺。解释动机可以放在后面，因为如果先解释，容易被听成辩解。修复也包括聆听对方版本，不急着纠正其中每个细节。道歉不是自我贬低，而是对关系的负责；原谅也不是立刻恢复原状，而是双方重新建立安全感和边界。若伤害反复发生，修复需要具体行为变化，而不只是情绪表达。App 可用于道歉、冷战后复联、伴侣争吵、朋友误会、亲子冲突和职场关系恢复。', '["关系修复", "道歉", "影响", "安全感", "冷战", "亲密关系", "沟通模板"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 500, now()),
(100036, '福格行为模型：行为发生要同时具备动机、能力与提示', '当用户说“我知道该做但就是做不到”时，优先从行为设计入手。一个行为要发生，通常需要动机足够、能力门槛足够低、提示在正确时间出现。动机最不稳定，不能把改变押在热血上；更可靠的方式是把行为缩小到几乎不会失败，并绑定已有习惯。比如“刷牙后做一次深呼吸”“进门后先问一句今天怎么样”。先让行为发生，再让身份感和自信跟上。', '["行为改变", "福格模型", "微习惯", "动机", "提示", "自控"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 36, now()),
(100037, '微习惯设计：小到不会失败，才容易长期坚持', '很多改变失败不是因为目标太小，而是第一步太大。微习惯的关键是把行动拆到两分钟内可完成，先追求“出现”而不是“完美”。用户想读书，可先设为“打开书读一段”；想运动，可先设为“穿上鞋出门站一分钟”。完成后及时给自己一个正向标记，让大脑把新行为和成就感连接起来。稳定后再自然加量，而不是一开始靠逼迫冲刺。', '["微习惯", "行动设计", "成长", "自我效能", "坚持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 37, now()),
(100038, '习惯回路：找出提示、惯常行为和奖励', '习惯不是单个动作，而是“提示—惯常行为—奖励”的回路。想改变坏习惯，先观察它通常在什么时候、什么情绪、什么地点、和谁在一起时发生，再识别真正奖励：是放松、逃避压力、获得刺激，还是寻求连接。不要只删除行为，而要保留奖励、替换动作。例如压力大就刷短视频，可能真正需要的是短暂恢复；可替换成五分钟散步、伸展或给朋友发一句话。', '["习惯回路", "行为改变", "奖励", "提示", "替代行为"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 38, now()),
(100039, '自控力不是硬扛，而是提前设计环境', '自控力资料的核心提醒是：越到诱惑现场才靠意志力，越容易失败。更有效的是提前改环境，让好行为更容易、坏行为更麻烦。想少刷手机，把手机放远、关通知、设置固定查看窗口；想控制饮食，不把高诱惑食物放在手边；想避免情绪化回复，先写草稿不发送。自控不是讨厌自己，而是承认人会受情境影响，然后温和地设计情境。', '["自控力", "环境设计", "意志力", "诱惑", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 39, now()),
(100040, '拖延的背后常是情绪调节，而不是懒', '拖延往往不是时间管理问题，而是情绪管理问题：任务让人感到羞耻、恐惧、无聊或无力，于是大脑选择短期缓解。处理拖延时，不要只问“怎么提高效率”，先问“我在回避哪种感受”。可把任务拆成下一步可见动作，并设置低压力开始仪式：只做五分钟、只写标题、只打开文件。开始后焦虑下降，行动会反过来带来掌控感。', '["拖延", "情绪调节", "行动", "自我效能", "任务拆解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 40, now()),
(100041, '认知觉醒：改变先从注意力回到当下开始', '成长不是一口气重塑人生，而是逐步看见自动反应。认知觉醒强调把注意力从模糊焦虑拉回具体事实：我现在在想什么、身体有什么感觉、下一步最小行动是什么。用户陷入“我不行、来不及、都完了”时，可先把大问题拆成可观察的场景和可执行的十分钟行动。觉察不是想明白一切，而是让自己从自动驾驶切回主动驾驶。', '["认知觉醒", "注意力", "自我改变", "行动", "觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 41, now()),
(100042, '成长型改变：先做实验，不急着定义自己', '当用户把一次失败解释成“我就是这种人”，改变会被身份标签锁死。更好的语言是实验：这次策略不适合我，下一次换一个提示、环境或支持方式。把改变当实验，可以降低羞耻感，也能保留复盘能力。每次只调整一个变量，例如时间、地点、同行者、任务大小或奖励方式。真正重要的不是一次做对，而是形成可迭代的自我更新系统。', '["成长", "实验思维", "复盘", "身份", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 42, now()),
(100043, '焦虑自助：先区分真实问题和假想灾难', '焦虑会把可能性伪装成确定性，让人提前生活在最坏结果里。处理时先写下担心内容，再分成两类：真实可行动的问题，和目前无法验证的灾难想象。前者列出下一步行动；后者练习延迟担心、回到身体和现实证据。不要和焦虑争辩“别想了”，而是问：我现在能做哪一个具体动作？如果不能行动，我能否先照顾身体，让神经系统降档？', '["焦虑", "认知行为", "担心", "情绪调节", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 43, now()),
(100044, '情绪粒度：说得越准确，越容易选对行动', '“我很烦”通常太粗糙，无法指导行动。情绪粒度训练是把模糊难受细分：委屈、羞耻、嫉妒、失望、担心、孤独、被忽视、无力、愤怒。不同情绪需要不同回应：失望需要调整期待，羞耻需要自我接纳，愤怒常提示边界，孤独提示连接需求。App 回答情绪问题时，应先帮用户命名感受，再从感受背后的需要进入行动建议。', '["情绪", "情绪粒度", "自我觉察", "需要", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 44, now()),
(100045, '情绪急救：心理小伤也要及时处理', '拒绝、孤独、失败、反刍和自责就像心理擦伤，如果不处理会扩大成长期痛苦。情绪急救的重点不是立刻积极，而是防止二次伤害：不要用一次拒绝证明自己不值得，不要让失败变成全面否定，不要在脑内反复播放羞辱场景。可用三步处理：承认受伤，给出多个解释，做一个能恢复自尊或连接的小行动。', '["情绪急救", "拒绝", "孤独", "失败", "自尊"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 45, now()),
(100046, '创伤反应：身体会先于理性进入防御', '创伤相关资料提醒，很多“反应过度”其实是身体把当下误判为过去的危险。用户突然僵住、爆发、逃离、麻木，并不一定是矫情，而可能是神经系统进入战斗、逃跑、冻结或讨好。支持方式不是逼自己马上讲道理，而是先恢复安全：看见周围环境、触碰稳定物体、慢慢呼气、让身体知道此刻已经不同于过去。稳定后再处理故事和意义。', '["创伤", "身体反应", "安全感", "神经系统", "疗愈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 46, now()),
(100047, '愤怒的积极功能：它常在提醒边界被侵犯', '愤怒并不总是坏情绪，它常提示某个边界、价值或需求被忽视。问题不在愤怒本身，而在表达方式。用户生气时可先问：我在保护什么？我希望对方停止什么、开始什么、理解什么？等身体降温后，用边界句表达：“当发生 X 时，我感到 Y，因为我需要 Z；下次请具体做 A。”这样既不压抑愤怒，也不让愤怒变成攻击。', '["愤怒", "边界", "情绪管理", "需求", "表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 47, now()),
(100048, '抑郁低谷：先恢复行动循环，再追求意义感', '抑郁状态会让人失去动力，而失去行动又会进一步降低情绪。支持用户时，不宜只说“想开点”。更实用的是行为激活：每天安排极小、可完成、可记录的行动，如洗澡、晒太阳、走五分钟、整理一小块桌面、联系一个安全的人。行动不是为了立刻开心，而是重建“我还能影响一点点生活”的证据。必要时建议寻求专业支持。', '["抑郁", "行为激活", "低谷", "行动", "支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 48, now()),
(100049, '反刍思维：把脑内复盘变成纸面问题', '反刍会让人以为自己在解决问题，实际是在重复痛苦。识别标志是：想了很久却没有新信息、没有行动、情绪更糟。可把脑内循环写成三个问题：我正在反复想哪句话？它对应的事实证据是什么？我能采取的最小行动是什么？如果没有行动，就给担心设置时间盒，转向身体活动或连接他人。把想法落到纸面，能把情绪风暴变成可处理对象。', '["反刍", "焦虑", "情绪急救", "书写", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 49, now()),
(100050, '存在焦虑：意义不是找到标准答案，而是承担选择', '存在主义心理治疗提醒，人的痛苦不只来自症状，也来自自由、孤独、死亡和意义感。用户问“我到底为什么活着”时，不必急着给鸡汤答案。可以引导其看见：意义往往不是被发现的固定物，而是在选择、关系、创造和承担中生成。先从一个愿意负责的小选择开始：今天我想怎样对待身体、关系、工作或某个重要价值？', '["存在主义", "意义感", "选择", "自由", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 50, now()),
(100051, '依恋系统：亲密关系里的追和躲都是求安全', '亲密关系中的“追问”和“冷处理”常不是单纯作或无情，而是两种安全策略。焦虑型通过靠近、确认、解释来降低不安；回避型通过拉开距离、沉默、强调独立来恢复掌控。若双方只攻击表层行为，就会形成越追越逃。修复时要翻译需求：追的一方需要可预期回应，躲的一方需要不被淹没的空间。先约定冷静时长和恢复沟通时间，比无限争对错更有效。', '["依恋", "亲密关系", "追逃循环", "安全感", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 51, now()),
(100052, '爱的五种语言：用对方能接收的方式表达爱', '很多关系并非没有爱，而是表达通道错位。爱的五种语言包括肯定的话语、高质量陪伴、接受礼物、服务行动和身体接触。用户可以观察伴侣最常抱怨什么、最常主动给出什么、最容易因什么感动，来判断主要爱语。关系经营不是只用自己喜欢的方式付出，而是学习对方能接收的方式，同时也清楚告诉对方自己需要什么。', '["亲密关系", "爱的五种语言", "伴侣", "表达爱", "需求"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 52, now()),
(100053, '伴侣冲突：先分清事实、解释和感受', '伴侣争吵常把事实、解释和感受混在一起：“你又不在乎我”其实可能包含事实“你迟到了三十分钟”、解释“你不重视我”、感受“我失望和不安”。修复时先拆开三层，事实越具体越少争议，解释越开放越能对话，感受越真诚越容易被听见。可以说：“你晚到三十分钟时，我脑中解释成自己不重要，所以很失落。我想知道实际发生了什么。”', '["伴侣沟通", "冲突修复", "事实", "感受", "解释"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 53, now()),
(100054, '亲子沟通：先连接，再纠正', '儿童沟通资料的一个关键原则是：孩子在被理解前很难真正听见道理。亲子冲突中，先描述孩子可能的感受和愿望，再谈规则与后果。比如“你很想继续玩，所以被叫停很生气”，比“别闹了”更能降低防御。连接不是纵容，而是先让孩子的大脑从对抗状态回到可学习状态。之后再给有限选择和清晰边界。', '["亲子沟通", "儿童心理", "连接", "边界", "情绪"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 54, now()),
(100055, '家庭关系中的边界：爱不是互相吞没', '家庭里常把“我都是为你好”当成越界理由。健康边界不是冷漠，而是区分谁的情绪、选择和后果由谁负责。用户面对父母、伴侣或孩子的压力时，可用三句式：我理解你的担心；这件事我会自己决定；我愿意在某个范围内和你讨论。边界需要温和重复，不必每次都证明自己有资格说不。', '["家庭关系", "边界", "自主", "沟通", "责任"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 55, now()),
(100056, '人际游戏：反复上演的冲突通常有隐藏收益', '沟通分析资料强调，有些冲突像固定剧本：表面在解决问题，实际在重复熟悉角色，例如“你看我多可怜”“你总是错”“只有我能救你”。这些游戏会带来隐藏收益：避免真正亲密、证明旧信念、获得注意或逃避责任。识别方法是看结局是否总相似、情绪是否熟悉、双方是否越谈越远。退出游戏的第一步，是拒绝继续扮演被分配的角色。', '["沟通分析", "人际游戏", "关系模式", "责任", "冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 56, now()),
(100057, '讨好型关系：把“被喜欢”从生存需求降级为普通愿望', '讨好型模式会让人把别人的满意当作安全来源。用户需要练习把“希望被喜欢”与“必须被喜欢才能安全”分开。可以从低风险场景练习表达偏好：今天我想吃这个、这个时间我不方便、我需要考虑一下。每一次没有迎合却仍然安全，都会给神经系统新证据。边界不是突然强硬，而是逐步把自我带回关系中。', '["讨好型人格", "边界", "关系", "自我价值", "安全感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 57, now()),
(100058, '关键对话开场：用共同目的降低防御', '高风险对话开始前，先不要急着陈述立场，而要建立共同目的。共同目的回答的是：我们为什么值得继续谈？例如“我不是想追责，而是想让之后合作更顺”“我想谈这件事，是因为这段关系对我重要”。当对方感到你不是来羞辱或控制，才可能从防御转向合作。事实、感受和请求都应服务于共同目的。', '["关键对话", "共同目的", "安全感", "高难沟通", "合作"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 58, now()),
(100059, '非暴力沟通的难点：请求必须具体且可拒绝', '非暴力沟通不只是温柔说话。很多人把要求伪装成请求，例如“你能不能尊重我一点”。真正的请求要具体、当下、可执行、可拒绝，如“今晚十点前能否把行程告诉我”。如果对方不能拒绝，那更像控制；如果不够具体，对方不知道怎么做。清楚请求能让关系从猜测和指责转向协商。', '["非暴力沟通", "请求", "需要", "边界", "关系沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 59, now()),
(100060, '共情不是同意，而是准确理解对方的内在经验', '共情力的重点不是替对方辩护，也不是放弃自己的立场，而是先准确复述对方的感受、需要和处境。有效共情常包含三层：你经历了什么，你因此有什么感受，这背后什么对你重要。共情之后仍可以设边界。比如“我听见你很委屈，也很想被支持；同时我不能接受用吼叫继续谈。”这样既连接，也不纵容。', '["共情", "倾听", "边界", "沟通", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 60, now()),
(100061, 'NLP地图：人回应的是自己的解释系统', '沟通中，别人不是直接回应现实，而是回应自己脑中的地图：经验、信念、价值和语言习惯。同一句话可能被理解成建议、批评、控制或关心。遇到误解时，不要只重复原话，可换一种感官通道和框架：给画面、给步骤、给感受、给选择。先理解对方地图，再邀请对方更新地图，比强迫对方接受自己的版本更有效。', '["NLP", "地图不是疆域", "沟通", "信念", "换框"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 61, now()),
(100062, '语言风格会透露关系位置和情绪距离', '语言风格资料提醒，词语不只传递内容，也传递关系位置。频繁使用绝对化词汇会增加压迫感；大量“你总是、你从不”容易引发防御；只讲道理不说感受，会让亲密关系变冷；过度道歉可能暴露低位和讨好。App 在润色沟通话术时，应把攻击性判断改成具体事实，把绝对化改成当下情境，把隐藏需求说清楚。', '["语言风格", "沟通", "关系位置", "表达", "冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 62, now()),
(100063, '影响力原则：先建立可信度，再提出请求', '影响力不是操控，而是降低对方理解和决策成本。常见有效因素包括互惠、承诺一致、社会认同、喜好、权威和稀缺。但在关系和咨询场景中，最重要的是可信度与尊重。先说明共同利益、展示理解、给出选择，再提出具体请求。若只利用技巧压迫对方，即使短期有效，也会破坏信任。', '["影响力", "说服", "信任", "请求", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 63, now()),
(100064, '金字塔表达：先给结论，再给理由和行动', '用户需要向伴侣、客户或团队说明复杂问题时，可使用金字塔结构：先说核心结论，再给三到四个理由，最后给下一步行动。这样能减少对方在信息中的迷路感。情绪沟通也可借用：我的结论是我希望我们调整相处方式；理由是最近三次约定都失效、我感到不安、我仍重视关系；下一步是我们约定一个可执行规则。', '["金字塔原理", "表达结构", "沟通", "结论先行", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 64, now()),
(100065, '谈判不是压倒对方，而是扩大可交换资源', '谈判资料适合转化为关系协商建议：不要只盯一个立场，而要找背后的利益。双方争“谁对谁错”时，资源只有面子；转向“各自真正想保护什么”时，可能出现时间、方式、顺序、补偿、试行期等多个变量。好的谈判不是让一方认输，而是创造比僵持更好的交换方案。', '["谈判", "利益", "协商", "冲突解决", "双赢"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 65, now()),
(100066, '九型领导力：不同型号需要不同反馈方式', '九型用于管理和关系时，不是贴标签，而是调整沟通入口。1号重标准，反馈要具体且尊重其原则；2号重关系，先肯定付出再邀请表达需求；3号重成果，给清晰目标和真实反馈；4号重独特和意义，避免轻率否定感受；5号重边界，提前给信息；6号重安全，说明依据与风险；7号重自由，给选择；8号重直接，少绕弯；9号重和谐，要明确邀请其立场。', '["九型人格", "领导力", "反馈", "沟通", "团队"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 66, now()),
(100067, '人格识别：看注意力焦点，不只看外在行为', '同一种行为可能来自不同动机。努力工作可能是1号的责任、3号的成就、6号的安全、8号的掌控；照顾别人可能是2号的连接，也可能是9号避免冲突。识别九型时，应观察注意力自动被什么吸走：错误、需求、形象、缺失、边界、风险、可能性、力量还是和谐。动机比行为更稳定，也更适合给出成长建议。', '["九型人格", "识别方法", "动机", "注意力", "性格"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 67, now()),
(100068, '性格陷阱：早年适应策略长大后可能变成限制', '性格陷阱不是道德缺陷，而是曾经帮助人适应环境的策略在新场景中过度使用。比如过度警觉曾经保护自己，如今可能变成不信任；讨好曾经减少冲突，如今可能失去边界；控制曾经带来安全，如今可能压迫关系。成长不是否定过去的自己，而是感谢旧策略，再发展更多选择。', '["性格陷阱", "人格", "早年经验", "成长", "模式"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 68, now()),
(100069, '回避型模式：真正需要的不是消失，而是安全距离', '回避型用户常在关系变近时想逃，因为亲密被体验为压力、要求或失控。修复不是强迫自己立刻完全开放，而是学会表达安全距离：“我需要半小时冷静，但我会回来继续谈。”这样既保护空间，也减少对方被抛弃感。回避的成长方向，是把消失变成可预期的暂停，把独立变成有连接的独立。', '["回避型人格", "依恋", "亲密关系", "边界", "安全距离"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 69, now()),
(100070, '人格障碍资料的启发：先看长期模式和功能损害', '面对“TA 是不是某种人格障碍”的问题，App 不应轻易诊断，而要引导用户观察长期模式：是否跨场景反复出现，是否导致关系、工作或自我功能受损，是否难以通过普通沟通调整。可提供非诊断性建议：保护边界、记录事实、减少被拉入极端互动，必要时寻求专业评估。知识库应避免给人贴病理标签。', '["人格", "边界", "关系风险", "非诊断", "心理健康"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 70, now()),
(100071, '系统思考：不要只盯事件，要看结构和反馈回路', '系统思考提醒，很多问题不是单次事件，而是结构持续制造同样结果。关系里反复争吵，可能有追逃反馈回路；工作中总拖延，可能有目标过大、反馈太慢、奖励缺失的结构。提问时从“谁错了”升级为“什么结构让这个结果反复发生”。找到反馈回路后，改变一个杠杆点，比反复责备更有效。', '["系统思考", "反馈回路", "关系模式", "行为改变", "结构"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 71, now()),
(100072, '批判性提问：先问证据，再问替代解释', '学会提问适合提升 App 回答的思辨质量。用户陷入单一解释时，可引导其问：我有什么证据？证据是否可靠？还有没有其他解释？这个结论有没有忽略例外？如果最好的朋友遇到同样情况，我会怎样判断？批判性思维不是否定一切，而是让情绪化判断多经过一道证据和替代解释的过滤。', '["批判性思维", "提问", "证据", "替代解释", "认知"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 72, now()),
(100073, '第三选择：从你赢我输转向共同创造', '冲突中的两难常被卡成“按你的”或“按我的”。第三选择思维要求先暂停立场竞争，进入理解和共创：我先真正理解你，你也理解我，然后我们一起找一个比双方原方案更好的方案。它特别适合亲密关系和团队冲突，因为关系质量本身也是结果的一部分。不是折中到双方都不满意，而是扩大问题框架。', '["第三选择", "冲突解决", "共创", "协作", "思维模型"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 73, now()),
(100074, '社会性动物：人会被情境和群体强烈影响', '社会心理学提醒，人的行为不只来自性格，也受情境、规范、群体认同和他人期待影响。用户评价自己或他人时，不要过早归因为“人品就是这样”。可问：当时的压力、群体氛围、权威暗示、奖励惩罚、旁观者反应是什么？理解情境不是推卸责任，而是找到更有效的改变入口。', '["社会心理学", "情境", "群体", "归因", "行为"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 74, now()),
(100075, '态度改变：先降低威胁，再提供新经验', '态度很少因为被强行说服而改变。直接否定对方常会激发防御，让其更坚持原观点。更有效的是先承认其关切，再提供小的新经验或证据，让对方保留自尊地更新。亲密关系中也是如此：如果一开口就是“你错了”，对方会保护自我；如果先说“我理解你担心的是 X，同时我想补充 Y”，才更可能产生移动。', '["态度改变", "社会影响", "说服", "防御", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 75, now()),
(100076, '心智模型：同一问题要用多个镜头看', '高质量思维不是掌握一个万能模型，而是能切换镜头。遇到关系问题，可用依恋看安全感，用系统思考看互动回路，用非暴力沟通看需要，用九型看注意力焦点。遇到行动问题，可用习惯回路、福格模型和自控环境设计。多模型能避免把复杂人生简化成一句标签。', '["思维模型", "多元视角", "决策", "关系", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 76, now()),
(100077, '高品质思维：先选模型，再处理问题', '《30个高品质思维模型》OCR 后可提炼为一个实用原则：不要把所有问题都当成情绪、性格或努力问题。遇到选择困难，用机会成本和长期收益看；遇到反复冲突，用系统回路看；遇到沟通卡住，用换位和利益结构看；遇到目标失控，用拆解和反馈看。模型不是答案，而是提问方式。App 回答时可以先判断问题类型，再选择适合的思维框架，避免给出泛泛建议。', '["思维模型", "问题拆解", "决策", "系统思考", "反馈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 77, now()),
(100078, '人际吸引和自尊：关系问题常牵动自我评价', '社会心理资料显示，人际反馈会强烈影响自我评价。用户被冷落或拒绝时，痛苦不只来自事件，也来自“我是不是不值得”的解释。支持时应把事件和价值拆开：一次回应慢，不等于你没有价值；一次关系失败，不等于你不适合被爱。先稳住自尊，再决定是否沟通、调整期待或离开。', '["自尊", "人际关系", "拒绝", "社会心理", "安全感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 78, now()),
(100079, '人生阶段：成长任务会随着年龄和角色改变', '成年发展心理学提醒，不同阶段的核心任务不同：建立身份、亲密关系、事业责任、照顾下一代、重新整合意义。用户的困惑不一定是退步，可能是旧阶段策略无法满足新阶段任务。App 回答时可问：你现在处在人生哪个转折？这个问题是在要求你发展什么新能力？这样能把焦虑转化为发展任务。', '["成年发展", "人生阶段", "成长任务", "身份", "意义"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 79, now()),
(100080, '人性的弱点：被重视感是沟通的底层需求', '人际沟通中，很多人首先需要感到被尊重、被看见、被认真对待。赞美、记住名字、真诚兴趣、少批评多理解，并不是讨好技巧，而是在满足基本的被重视需求。用于 App 建议时，应避免机械取悦，而是提醒用户：先让对方感到自己不是被审判的对象，再提出观点或请求。', '["人际沟通", "尊重", "被看见", "关系", "表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 80, now()),
(100081, 'NLP目标框架：把愿望改写成可执行结果', 'NLP 资料适合转化为 App 的目标澄清工具：不要只说“我不要焦虑、不要吵架、不要拖延”，而要改成正向、具体、可验证、由自己能启动的结果。例如“我想在冲突开始后先暂停三十秒，再用事实和需要表达”。一个好目标要能回答：我想要什么，何时何地发生，如何知道达成，它对我和关系是否生态，第一步由谁开始。这样能把模糊愿望转为行动脚本。', '["NLP", "目标设定", "行为改变", "可执行", "正向目标"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 81, now()),
(100082, 'NLP感知位置：从我、你、旁观者三角度重看冲突', '处理冲突时，可用 NLP 的感知位置练习。第一位置是我：我看见什么、感到什么、需要什么；第二位置是对方：如果我是 TA，可能害怕什么、想保护什么；第三位置是旁观者：一个中立的人会如何描述双方互动。用户卡在委屈或愤怒中时，不要求立刻原谅，而是先切换观察位置。位置切换能降低单一叙事的黏性，让沟通从控诉转向理解和选择。', '["NLP", "感知位置", "换位思考", "冲突修复", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 82, now()),
(100083, 'NLP逻辑层次：别在身份层攻击，只在行为层调整', '沟通中最容易伤人的错误，是把行为问题上升到身份否定：“你就是自私”“我就是没用”。NLP 的逻辑层次可帮助拆分：环境、行为、能力、信念价值、身份、使命。越高层越敏感，越低层越可改。反馈别人时，应尽量落在具体行为和影响上；鼓励自己时，可以把失败从身份层降回策略层：不是我不行，而是这个方法、环境或能力训练还需要调整。', '["NLP", "逻辑层次", "身份", "反馈", "自我价值"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 83, now()),
(100084, 'NLP亲和感：先校准对方状态，再推动观点', '高效沟通不是急着输出观点，而是先建立亲和感。亲和不等于讨好，而是观察对方的节奏、情绪、用词和关注点，让对方感到被接上。用户想说服或修复关系时，可先复述对方关键词，确认理解，再提出自己的需要。若对方在压力中，先降低语速、减少结论、给出选择；若对方重结果，就给结构和下一步。先连接频道，再传递内容。', '["NLP", "亲和感", "校准", "影响力", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 84, now()),
(100085, 'NLP换框：问题行为背后常有未被满足的正向意图', '换框不是强行积极，而是寻找行为背后的功能。拖延可能在保护人免于羞耻，冷处理可能在保护人免于被淹没，控制可能在追求安全。识别正向意图后，仍要评估旧策略是否有代价，再寻找更成熟的替代方式。这样既不纵容问题行为，也不把人简单定罪。App 在回答关系和成长问题时，可先问“这个反应原本想帮你避免什么”。', '["NLP", "换框", "正向意图", "行为模式", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 85, now()),
(100086, '语言风格：功能词比大道理更透露心理状态', '语言风格资料强调，真正透露心理状态的往往不是华丽内容词，而是人称、虚词、连接词、否定词、时态等小词。一个人频繁使用“我”可能处在自我关注或压力中；大量绝对化词汇会让表达更封闭；过多否定和转折可能显示防御或矛盾。用于 App 时，不应把单个词当诊断，而是把语言线索作为理解用户情绪、关系位置和注意力焦点的辅助证据。', '["语言风格", "功能词", "心理线索", "自我觉察", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 86, now()),
(100087, '人称代词：我、你、我们会改变关系气氛', '沟通话术里，人称代词会影响关系气氛。只说“你怎么总是”容易让对方感到被审判；只说“我都怪我”容易让自己陷入低位；适度使用“我们”能提示共同面对问题，但若用“我们”掩盖个人责任，也会显得逃避。更成熟的表达是：我为自己的感受和请求负责，你为你的选择负责，我们一起决定下一步规则。', '["人称代词", "关系沟通", "责任", "表达", "语言风格"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 87, now()),
(100088, '语言同步：相似的表达节奏能增加被理解感', '语言风格研究提示，人在连接顺畅时，表达节奏、词类和关注点会自然靠近。关系沟通中，可以有意识地先使用对方熟悉的词和框架，再提出新观点。比如对方重视效率，就先谈结果和步骤；对方重视感受，就先谈体验和影响。同步不是模仿操控，而是降低理解成本。同步之后再温和引入不同意见，通常比直接反驳更容易被听见。', '["语言同步", "沟通", "亲和感", "表达节奏", "理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 88, now()),
(100089, '从绝对化语言回到具体事实', '冲突中的“总是、从不、每次、所有人都”会迅速放大威胁，让对方进入辩解。语言风格资料可用于提醒用户把绝对化改成具体事实：把“你从来不关心我”改成“这周三次我提到难受时，你都没有继续问”；把“我永远做不好”改成“这次演示有两处没有准备充分”。事实越具体，越能讨论；标签越绝对，越容易卡住。', '["绝对化语言", "事实表达", "冲突降温", "沟通", "认知"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 89, now()),
(100090, '书写能帮助整理情绪叙事', '语言与心理研究显示，把混乱经历写出来，能帮助人把情绪、事实和意义重新组织。App 可以引导用户做三段式书写：发生了什么；我当时有哪些感受和身体反应；这件事触碰了我什么需要，以及下一步我能做什么。书写不是为了美化痛苦，而是把脑内反刍转为外部文本，使人更容易看见模式、选择行动。', '["书写疗愈", "情绪整理", "反刍", "语言", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 90, now()),
(100091, '九型发展层级：同一型号也有健康和失衡差异', '《九型人格2》强调，同一人格类型不是固定表现，而会随健康水平呈现不同层级。健康状态下，类型天赋会服务于生命：1号正直、2号慈悲、3号真实高效、4号创造、5号洞察、6号勇敢、7号喜悦、8号保护、9号安定。失衡时，同一能量会扭曲成批判、索取、表演、沉溺、抽离、怀疑、逃避、控制或麻木。因此 App 使用九型时，应同时判断主型和状态，而不是看到一个行为就定型。', '["九型人格", "发展层级", "健康状态", "失衡", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 91, now()),
(100092, '九型误判：理想自我不等于真实类型', '很多人测九型时会把“我想成为的人”误认为“我真实的自动策略”。例如想显得善良而选2号，想显得强大而选8号，想显得理性而选5号。更可靠的识别方式，是看压力下最自动的防御、反复出现的恐惧和注意力焦点。真正的类型常让人有一点被看穿，而不只是感觉很喜欢。App 解读时应提示用户：问卷只是入口，动机和长期模式更重要。', '["九型人格", "误判", "理想自我", "动机", "识别方法"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 92, now()),
(100093, '九型应用：不要用类型限制人，要用类型增加选择', '九型知识容易被误用成标签：“我是6号所以我就是焦虑”“他是8号所以没法沟通”。更成熟的用法是看见自动模式，然后增加选择。类型解释了为什么某些问题反复出现，但不决定人只能这样。App 回答应避免“你就是某型所以必然如何”，而应说“如果你有这种模式，可以尝试发展相反能力”。九型的目标是自由，不是把人关进九个盒子。', '["九型人格", "标签风险", "自由", "成长", "自我超越"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 93, now()),
(100094, '九型矛盾感：人会在不同场景表现出多个类型影子', '用户常问“为什么我像好几个型号”。九型人格2的一个实用提醒是：人会在不同关系、压力和角色中呈现多个类型的影子，但核心类型仍看最深层动机和防御。一个人可以既慷慨又自私，既温和又攻击，既理性又情绪化；这些矛盾不一定说明类型混乱，而可能是侧翼、压力线、安全线、健康层级和社会角色共同作用。识别时要看长期重复的主旋律。', '["九型人格", "侧翼", "压力线", "情境", "识别方法"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 94, now()),
(100095, '九型关系建议：先看对方害怕失去什么', '九型用于关系沟通时，可以先问“这个型号最怕失去什么”。1号怕失去正确和尊严，2号怕失去被需要，3号怕失去价值和认可，4号怕失去真实自我，5号怕失去空间和资源，6号怕失去安全和支持，7号怕失去自由和可能性，8号怕失去掌控和脆弱保护，9号怕失去和谐。理解恐惧后，沟通更容易避开对方防御，也更能提出对方听得进去的请求。', '["九型人格", "关系沟通", "核心恐惧", "防御", "理解他人"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 95, now()),
(100096, '情绪亲密：亲密关系的核心是能共同承受真实情绪', '情绪亲密不是两个人永远开心，而是双方能在恐惧、羞耻、愤怒、悲伤和脆弱出现时仍保持连接。很多关系疏远不是因为没有爱，而是情绪一强就进入攻击、退缩、讲道理或转移。App 回答亲密关系问题时，可以引导用户先说“我此刻真实感到什么”，再说“我需要怎样被回应”。能被安全表达和接住的情绪，会成为关系更深的入口。', '["情绪亲密", "亲密关系", "脆弱", "安全感", "真实表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 96, now()),
(100097, '适应性情绪与非适应性情绪要分开处理', '情绪资料区分适应性和非适应性情绪。适应性恐惧提醒真实风险，适应性愤怒保护边界，适应性羞耻帮助人回到关系伦理；非适应性情绪则常来自旧创伤、过度解释或环境误判，会让人反复陷入不合比例的反应。处理时不要笼统压制情绪，而要问：这份情绪在当下是否提供有效信息？如果是，转化为行动；如果不是，先安抚身体和旧经验。', '["情绪管理", "适应性情绪", "恐惧", "愤怒", "羞耻"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 97, now()),
(100098, '羞耻感的修复：从我不好回到我做了什么', '健康羞耻能提醒人尊重边界和关系，但有毒羞耻会把具体行为变成身份否定：“我错了”变成“我这个人很糟”。用户陷入羞耻时，应先把身份和行为分开：我做了某件需要承担的事，不等于我没有价值。修复顺序是承认影响、承担责任、表达歉意、做出补偿，同时停止用自我攻击替代真实改变。', '["羞耻", "自我价值", "修复", "责任", "情绪亲密"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 98, now()),
(100099, '悲伤不是软弱，它帮助人承认失去并重新连接', '悲伤常被误解为负能量，但它的功能是帮助人承认失去、放下无法挽回的部分，并重新寻找连接。用户失恋、关系破裂或人生阶段结束时，不必急着“振作”。可以允许悲伤有时间、身体感和表达出口：哭、写下失去、讲给安全的人听、为告别做一个仪式。悲伤被看见后，人才能把爱和意义带入下一阶段。', '["悲伤", "失去", "情绪疗愈", "亲密关系", "告别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 99, now()),
(100100, '情绪表达要同时包含感受、需要和边界', '只表达情绪而没有需要，容易变成宣泄；只有边界而没有感受，容易显得冷硬；只有需要而没有边界，容易陷入讨好。情绪亲密中的成熟表达可以是：“我感到害怕和失落，因为我需要稳定回应；如果你需要空间，请告诉我多久后回来谈。”这类表达既让对方知道你内在发生了什么，也给出可协商的行动方向。', '["情绪表达", "需要", "边界", "关系沟通", "亲密"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 100, now()),
(100101, '愤怒控制：先识别身体预警，而不是等爆发后补救', '愤怒很少突然出现，身体通常会先给信号：心跳加快、肩颈绷紧、脸热、拳头握紧、呼吸变浅、声音提高。控制愤怒的第一步不是讲道理，而是建立预警清单。一旦信号出现，就先暂停、离开刺激源、延长呼气、喝水或让身体移动。越早在低强度阶段介入，越不需要在高强度爆发后道歉和修复。', '["愤怒管理", "身体信号", "暂停", "情绪调节", "自控"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 101, now()),
(100102, '愤怒情境记录：找出触发点、想法和后果', '控制愤怒需要记录模式。每次愤怒后可写四项：触发事件是什么；我当时脑中冒出的解释是什么；身体和行为如何反应；结果是解决了问题还是扩大了伤害。几次记录后，用户会看见常见触发点，如被否定、等待、失控、被催促或感到不公平。看见模式后，才能提前设计替代反应，而不是每次都以为只是对方惹我。', '["愤怒管理", "情境记录", "触发点", "认知", "复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 102, now()),
(100103, '破坏性愤怒与建设性边界要区分', '愤怒本身能提供边界信息，但破坏性愤怒会通过羞辱、威胁、冷暴力或攻击来伤害关系。建设性边界则把能量转成清楚要求：“这件事我不能接受”“我们暂停十分钟再谈”“下次请提前告诉我”。App 回答用户“我一生气就伤人”时，应同时承认愤怒背后的需求，并训练非伤害性的表达方式。目标不是没有愤怒，而是不让愤怒掌舵。', '["愤怒", "边界", "关系修复", "表达", "冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 103, now()),
(100104, '愤怒暂停协议：离开不是逃避，回来才是关键', '冲突升温时，暂停比继续争输赢更有用。但暂停必须有协议，否则会被体验成冷暴力或抛弃。可说：“我现在太激动，继续会伤人。我需要二十分钟冷静，八点二十回来继续谈。”暂停期间不反刍、不写攻击长文，而是降身体唤醒。关键是按约定回来，哪怕只先确认还愿意谈。这样既保护关系，也训练自我控制。', '["愤怒暂停", "冲突降温", "冷静期", "关系安全", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 104, now()),
(100105, '愤怒后的修复：不要只解释动机，要承认影响', '愤怒爆发后，很多人急着解释“我不是故意的”。但对方首先需要听见影响被承认。修复顺序可以是：我刚才提高音量/说了伤人的话；这让你感到害怕或受伤；这部分我负责；下次我会在身体信号出现时暂停；现在我想听听你的感受。解释动机可以放后面，不能替代承担影响。真正的道歉要带行为改变。', '["愤怒修复", "道歉", "影响", "责任", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 105, now()),
(100106, '抑郁康复：低谷中先建立支持网络，而不是独自硬扛', '抑郁相关案例资料提醒，走出低谷很少只靠一个人的意志力。用户陷入持续无力、绝望或自责时，应优先建立支持网络：可信任的亲友、专业咨询或医疗资源、规律作息、身体活动和危机联系人。支持不是替用户解决人生，而是在其能量最低时提供外部结构。App 回答时应鼓励用户把“我必须自己扛”改成“我可以借助系统恢复”。', '["抑郁", "支持系统", "康复", "心理健康", "低谷"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 106, now()),
(100107, '抑郁中的小行动：先恢复生活节律，再追求动力', '抑郁会让人等待“有动力再行动”，但恢复常常相反：先用极小行动恢复节律，再让动力慢慢回来。可从睡眠、饮食、晒光、洗漱、散步、联系一个安全的人开始，每天只记录是否完成，不用要求情绪立刻变好。小行动的作用不是证明自己强大，而是给大脑和身体重新建立可预测的安全感。', '["抑郁", "行为激活", "生活节律", "小行动", "恢复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 107, now()),
(100108, '双相和重度低谷：App 不做诊断，但要识别求助信号', '资料涉及抑郁和双相困境时，App 应保持非诊断原则：不根据聊天直接下诊断，但要识别风险信号。若用户出现持续失眠或嗜睡、明显功能下降、极端绝望、自伤念头、冲动高涨或情绪大幅波动，应建议尽快联系专业医生、咨询师或身边可信任的人。知识库给出的作用是陪伴、稳定和转介，不替代临床评估。', '["抑郁", "双相", "风险识别", "专业求助", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 108, now()),
(100109, '康复叙事：真实故事能给低谷者带来可恢复的证据', '抑郁康复案例的价值，不在于要求用户照搬别人的路径，而在于提供“人可以从深渊回来”的证据。App 回答低谷用户时，可以把康复描述为多因素过程：承认病痛、求助、调整环境、重建节律、学习情绪技能、逐步恢复关系和意义。避免把成功故事变成压力，而要把它变成希望：你不需要立刻好起来，只需要开始被支持。', '["康复故事", "希望感", "抑郁", "支持", "意义"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 109, now()),
(100110, '言语行为：一句话不仅传递信息，也在完成行动', '言语行为理论适合提升 App 的沟通建议：很多话不是单纯描述，而是在做事。道歉是在承担，承诺是在建立未来义务，请求是在邀请合作，指责是在分配责任，命令是在施加权力。因此沟通问题不能只看字面内容，还要看这句话完成了什么关系动作。用户想修复关系时，应选择能完成连接、澄清、承担和请求的语言，而不是无意识地完成攻击。', '["言语行为", "沟通", "道歉", "承诺", "关系动作"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 110, now()),
(100111, '承诺表达：说“我会”时要明确条件、时间和行动', '承诺是一种言语行为，会改变关系中的期待。模糊承诺如“我以后会改”容易让对方再次失望；有效承诺要包含具体行动、时间、条件和复盘方式。例如“下次争吵时我会先暂停十分钟，晚上九点回来继续谈”。App 给用户生成道歉或修复话术时，应避免空泛保证，改成可观察的承诺。', '["承诺", "言语行为", "关系修复", "道歉", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 111, now()),
(100112, '请求和要求：真正的请求允许对方回应和协商', '从言语行为角度看，请求、要求和命令会创造不同关系位置。请求承认对方有选择，要求带有更强压力，命令则假设权力差。亲密关系中很多“你能不能”其实是包装过的命令，难怪引发防御。更成熟的表达是说明需要、提出具体请求，并允许对方说明难处：“我希望今晚能聊十分钟，你现在方便吗？”', '["请求", "要求", "边界", "关系沟通", "协商"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 112, now()),
(100113, '亲子沟通：孩子行为背后常有能力缺口和情绪需求', '亲子资料提醒，孩子的问题行为不一定是故意作对，常常是情绪调节、表达能力、规则理解或连接需求不足。家长若只用批评和惩罚，短期可能压住行为，长期会削弱信任。更有效的是先翻译行为：孩子在保护什么、害怕什么、还不会什么？然后同时给连接和边界。App 回答亲子问题时，应避免把孩子标签化为懒、坏或不懂事。', '["亲子沟通", "儿童情绪", "行为背后", "连接", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 113, now()),
(100114, '亲子冲突：先处理情绪，再处理道理和规则', '孩子情绪上来时，大脑很难接收长篇道理。亲子冲突的顺序应是：先让孩子知道自己的感受被看见，再明确规则，再给选择和后果。例如“你很想继续玩，所以被叫停很生气；但睡觉时间到了。你可以现在收玩具，或我陪你收两分钟。”先连接不是纵容，而是让孩子从对抗状态回到可合作状态。', '["亲子冲突", "情绪处理", "规则", "选择", "合作"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 114, now()),
(100115, '家长权威：稳定、一致和尊重比吼叫更有力量', '有效家长权威不是声音大，而是规则稳定、边界一致、态度尊重。孩子需要知道什么可以协商，什么不能越界，以及越界后会发生什么。若家长情绪化地时松时紧，孩子会不断测试边界。App 可建议家长提前约定少量关键规则，用简短语言重复，并在执行时减少羞辱。温和和坚定可以同时存在。', '["亲子教育", "权威", "规则", "边界", "稳定"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 115, now()),
(100116, '培养孩子自我价值：多肯定努力、选择和品格', '亲子关系中，孩子不只需要被评价成绩，也需要确认自己作为人的价值。家长可以多肯定具体努力、选择、品格和成长：“你刚才虽然生气，但还是回来谈了”“你愿意尝试新方法”。这类反馈比泛泛说“你真棒”更能建立内在自我价值。App 回答亲子问题时，可把关注点从控制孩子转向发展孩子能力。', '["亲子关系", "自我价值", "肯定", "成长", "能力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 116, now()),
(100117, '情绪是一种语言：每种情绪都在传递信息', '《情绪的语言》可提炼为核心原则：情绪不是需要消灭的噪音，而是身体和心理的语言。恐惧提示风险，愤怒提示边界，悲伤提示失去，羞耻提示关系伦理，嫉妒提示渴望和比较。App 回答情绪问题时，不应只让用户“别想太多”，而要帮助翻译：这份情绪想告诉我什么？它指向什么需要？我能采取什么成熟行动？', '["情绪语言", "情绪管理", "需要", "边界", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 117, now()),
(100118, '恐惧的功能：不是阻止行动，而是要求检查安全', '恐惧的作用是提示风险和未知。健康恐惧会让人收集信息、设定边界、做好准备；失衡恐惧则会让人冻结、逃避或过度想象。用户害怕时，可以先感谢恐惧在保护自己，再问：我需要确认什么事实？需要什么支持？最小安全行动是什么？这样恐惧从敌人变成风险评估系统。', '["恐惧", "安全", "风险评估", "情绪语言", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 118, now()),
(100119, '嫉妒的信息：看见自己真正渴望什么', '嫉妒常被羞耻化，但它也能暴露真实渴望。看到别人拥有关系、成就、自由或关注时，用户可以问：我羡慕的到底是什么？这代表我也想发展哪种能力或生活？成熟处理嫉妒，不是贬低对方，也不是贬低自己，而是把比较转化为愿望和行动。嫉妒被翻译后，可能成为自我探索的入口。', '["嫉妒", "渴望", "比较", "情绪语言", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 119, now()),
(100120, '悲痛需要仪式和见证，而不是被催促放下', '悲痛是失去之后的深层情绪，它需要时间、仪式和见证。如果一个人被催促“别难过了”，悲痛可能转入麻木或长期反刍。App 支持悲痛用户时，可引导其说出失去了什么、这份关系或阶段曾代表什么、想如何纪念和告别。放下不是遗忘，而是让爱和意义找到新的位置。', '["悲痛", "失去", "仪式", "情绪疗愈", "告别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 120, now()),
(100121, '简快疗法：改变不一定要长期分析全部过去', 'NLP 简快心理疗法强调，改变可以从当前资源、目标状态和可重复的新反应开始，而不一定要把所有过去细节分析完。App 可把它转化为实用问法：你想从现在的困境走向什么状态？你过去哪怕短暂体验过这种状态吗？当时有什么资源？下一次触发时，你能做哪个不同动作？这种取向适合把用户从反复解释带回行动练习。', '["NLP", "简快疗法", "资源", "目标状态", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 121, now()),
(100122, '资源取向：先找到用户已经拥有的例外经验', '当用户说“我从来做不到”时，简快疗法会寻找例外：有没有一次稍微好一点？有没有某个人、场景或状态下你能做到一点？例外不是否认问题，而是证明系统中已有资源。App 可以追问例外发生的条件，然后把它复制到新情境。比起只分析失败，寻找例外更能激活自我效能。', '["资源取向", "例外经验", "自我效能", "NLP", "改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 122, now()),
(100123, '次感元调整：改变内在画面会影响情绪强度', 'NLP 资料中常用内在表征理解情绪：同一记忆如果画面很大、很近、很亮、声音很强，情绪会更强；如果把画面拉远、变小、变暗，身体反应可能下降。App 可把这作为非临床的自我调节练习：当某个画面反复刺激你时，试着在想象中调节距离、大小和声音，同时回到呼吸和当下环境。', '["NLP", "次感元", "情绪调节", "想象", "自助练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 123, now()),
(100124, '信念松动：把绝对句改成可更新假设', '很多痛苦来自僵硬信念，如“我永远不被爱”“我一定会失败”。简快取向会把绝对信念改成可检验假设：在什么情境下它不完全成立？有没有反例？如果它只是旧保护策略，我现在能否更新它？App 回答时可帮助用户从身份化结论转向可调整信念，让改变有入口。', '["信念", "NLP", "认知调整", "绝对化", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 124, now()),
(100125, '沟通分析：关系互动中常有父母、成人、儿童三种自我状态', '沟通分析资料可转化为 App 的互动识别工具：人在交流时可能从父母自我状态说话，表现为批评、教导、保护；从成人自我状态说话，表现为事实、选择和协商；从儿童自我状态说话，表现为反抗、讨好、委屈或玩耍。冲突升级时，常是双方从成人状态滑入父母对儿童、儿童对父母。修复的关键是把话语拉回成人状态：讲事实、说感受、提请求、谈后果。', '["沟通分析", "自我状态", "成人状态", "关系沟通", "冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 125, now()),
(100126, '心理游戏：反复冲突背后常有熟悉但痛苦的脚本', '伯恩的人际游戏理论提醒，很多关系冲突表面在讨论事情，实际在重复固定脚本：受害者等待被拯救，拯救者过度负责后委屈，迫害者用指责获得控制。游戏的结局通常很熟悉：双方都证明了自己的旧信念。App 可帮助用户识别：这场争吵是不是又走到同一个结局？我正在扮演哪个角色？我能否退出脚本，改用成人状态表达需要和边界？', '["心理游戏", "沟通分析", "戏剧三角", "关系模式", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 126, now()),
(100127, '退出人际游戏：不接角色，回到真实请求', '退出心理游戏不是赢过对方，而是不再接下被分配的角色。对方指责时，不进入反击；对方求救但拒绝负责时，不急着拯救；自己想委屈控诉时，先问真正请求是什么。可用句式：“我愿意谈具体问题，但不接受互相羞辱。”“你希望我具体怎么帮？哪一步由你自己做？”把隐藏交易改成明说请求，游戏就失去动力。', '["人际游戏", "退出脚本", "真实请求", "边界", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 127, now()),
(100128, '亲密与自主：好的关系不是玩游戏，而是直接表达', '沟通分析的成长方向是从心理游戏走向自主和亲密。自主意味着能觉察自己的脚本，而不是自动重复；亲密意味着能直接表达真实感受和需要，而不是用拐弯、测试、讽刺或冷战获取回应。App 在关系咨询中可引导用户把“你猜我怎么了”换成“我现在需要被听见”，把测试对方换成清楚请求。', '["亲密关系", "自主", "沟通分析", "真实表达", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 128, now()),
(100129, '儿童心理：不要把成人逻辑直接套到孩子身上', '儿童心理学提醒，孩子不是缩小版成人。不同发展阶段的注意力、情绪调节、语言表达、因果理解和自我控制能力都不同。家长如果用成人标准要求孩子“马上懂事”，容易把能力不足误解成故意作对。App 回答亲子问题时，应先判断孩子可能处于什么发展阶段，再给出符合年龄的规则、选择和练习。', '["儿童心理", "发展阶段", "亲子教育", "情绪调节", "能力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 129, now()),
(100130, '儿童问题行为：先看发展任务，再看教育方法', '孩子的退缩、攻击、撒谎、拖延或哭闹，可能对应不同发展任务：争取自主、寻求连接、表达挫败、测试边界或回避羞耻。处理时先问这个行为在孩子的发展中服务什么，而不是直接贴坏习惯标签。家长需要同时提供安全关系和稳定边界，让孩子在可承受的范围里学习表达、等待、协商和承担后果。', '["儿童行为", "亲子关系", "发展任务", "边界", "情绪"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 130, now()),
(100131, '家长焦虑会进入孩子系统', '儿童心理资料强调，家长的焦虑、冲突和不稳定会影响孩子的安全感。孩子很多时候不是听家长说什么，而是感受家庭气氛。若父母长期紧张、指责或忽冷忽热，孩子可能用问题行为表达系统压力。App 可建议家长先调节自身情绪，再处理孩子行为：降低音量、明确规则、减少羞辱、保持可预测的回应。', '["家长焦虑", "儿童安全感", "家庭系统", "亲子沟通", "情绪"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 131, now()),
(100132, '拖延循环：短期逃避会强化长期焦虑', '拖延症资料指出，拖延的即时奖励是缓解不舒服：不用面对失败、评价、无聊或复杂任务。但短期舒服会带来长期焦虑，下一次更想逃。破循环的关键不是骂自己，而是识别“我正在用逃避换短暂轻松”。可以把任务拆到五分钟，先开始而不追求完成，并在开始后记录焦虑是否下降。行动会削弱拖延带来的假奖励。', '["拖延", "逃避", "焦虑", "行动", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 132, now()),
(100133, '拖延背后的完美主义：宁可不做也不愿做得不够好', '很多拖延来自完美主义：任务一旦开始，就可能暴露不足，所以大脑选择延后。用户可练习“低质量初稿”策略：先允许做出粗糙版本，再修改。把目标从一次做好改成先产生材料；把评价从结果改成是否开始。对完美型用户尤其重要：完成一个可改进的版本，比等待理想状态更接近真实成长。', '["拖延", "完美主义", "初稿", "行动", "自我接纳"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 133, now()),
(100134, '反拖延计划：明确下一步、开始时间和障碍预案', '有效反拖延计划要具体到下一步，而不是写“我要努力”。格式可以是：在什么时间、什么地点、做哪一个动作、做多久、如果遇到阻碍怎么办。例如“晚饭后八点，在书桌前打开文档写标题十分钟；如果想刷手机，就把手机放到客厅”。计划越可执行，越不依赖临时情绪。', '["反拖延", "计划", "执行意图", "障碍预案", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 134, now()),
(100135, '人际沟通：先听懂，再回应，而不是准备反驳', '人际沟通技巧资料强调，倾听不是沉默等待自己发言，而是主动理解对方的事实、感受和需要。有效回应可以先复述：“我听到你在意的是……你感到……对吗？”这会降低防御，让对方感到被看见。App 在生成沟通建议时，应先给倾听句，再给表达句，避免用户一上来就输出立场。', '["人际沟通", "倾听", "复述", "理解", "关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 135, now()),
(100136, '表达感受时少用指责，多用我信息', '“你让我很痛苦”容易让对方防御；“我在这件事里感到难过和不安”更容易被听见。我信息不是只谈自己，而是把事实、感受、影响和请求组合起来：当发生 X 时，我感到 Y，因为它影响 Z；我希望下次 A。这样既表达真实，又减少攻击。App 可把用户的指责句自动改写为我信息。', '["我信息", "感受表达", "人际沟通", "冲突降温", "请求"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 136, now()),
(100137, '反馈技巧：具体行为比人格评价更有建设性', '给反馈时，评价人格会引发羞耻和抵抗；描述具体行为更可能带来改变。把“你不负责任”改成“这次约定的材料周三没有提交，导致项目延迟一天”。再说明影响、询问原因、共同制定下一步。无论亲密关系还是职场，反馈都应落在可观察行为上，而不是给人贴稳定标签。', '["反馈", "行为描述", "职场沟通", "关系沟通", "建设性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 137, now()),
(100138, '界限沟通：温和语气加清楚底线', '很多人以为有边界就必须强硬，其实边界可以温和但清楚。有效边界包含三部分：我理解你的处境；我能做的范围是；超出范围我不会做。比如“我知道你很急，我今晚可以帮你看十分钟，但不能替你完成全部。”温和让关系保持连接，清楚让对方知道规则。边界模糊才更容易积怨和爆发。', '["边界", "人际沟通", "底线", "温和坚定", "关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 138, now()),
(100139, '人格模式：先观察长期重复，而不是给人贴诊断', '人格障碍相关资料适合给 App 提供非诊断性框架：不要因为一次冲突就说某人是某种人格障碍，而要观察长期、跨场景、反复出现的模式，以及它是否造成关系、工作和自我功能受损。App 回答时应聚焦行为模式、边界和求助建议，而不是替用户给自己或他人下临床诊断。这样既能保护用户，也避免把复杂关系简化成标签。', '["人格模式", "非诊断", "关系风险", "边界", "心理健康"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 139, now()),
(100140, '人格障碍的认知视角：核心信念会驱动反复行为', '认知治疗资料强调，很多持久的人格模式背后有核心信念，例如“别人会伤害我”“我必须控制才安全”“我不值得被爱”“如果被拒绝就完了”。这些信念会让人选择性解读关系，并反复触发防御行为。App 可帮助用户把冲突从“我就是这样”拆成“我在什么信念下自动反应”，再寻找更平衡的新信念和行为实验。', '["认知治疗", "核心信念", "人格模式", "行为实验", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 140, now()),
(100141, '边缘化互动：强烈情绪下先稳定，再讨论关系结论', '人格障碍治疗资料中反复强调，强烈情绪会让关系判断变得极端：全好或全坏、亲密或抛弃、信任或背叛。App 不做诊断，但可给出稳定策略：当情绪强度过高时，先暂停关系结论，回到身体、事实和当下安全；等情绪降到可对话范围，再讨论事件、感受和请求。不要在情绪顶点做分手、拉黑、报复等重大决定。', '["强烈情绪", "关系判断", "稳定", "人格模式", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 141, now()),
(100142, '回避和依赖模式：一个怕靠近，一个怕分离', '人格相关资料可帮助理解两类关系困难：回避模式把亲密体验为压力和被吞没，因此倾向退缩；依赖模式把分离体验为危险，因此倾向黏附、确认和难以独立。App 回答关系问题时，可把表层行为翻译成安全需求，同时提醒用户发展相反能力：回避者练习可预期回应，依赖者练习自我安抚和独立选择。', '["回避", "依赖", "亲密关系", "安全感", "人格模式"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 142, now()),
(100143, '人格改变：不是消灭自己，而是增加反应选择', '认知行为疗法看重具体练习：识别触发情境、自动想法、情绪强度、行为后果，再设计新反应。人格改变不是否定整个人，而是让原本单一的防御策略多出选择。用户若总是攻击、讨好、退缩或控制，可以先记录触发点，再练习一个更小的新动作：停顿、提问、表达需要、设边界或寻求支持。', '["人格改变", "认知行为", "触发点", "新反应", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 143, now()),
(100144, '需求层次：先满足基础安全，再谈自我实现', '动机与人格资料提醒，人的成长需要基础条件。若用户长期缺睡、缺安全、缺支持、经济或关系高度不稳，却要求自己立刻自我实现，容易变成自责。App 可先判断问题处在哪一层需求：生理、安全、归属、尊重还是自我实现。越底层的需求越需要具体支持和稳定结构；越高层的需求越适合谈意义、创造和潜能。', '["需求层次", "马斯洛", "安全感", "自我实现", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 144, now()),
(100145, '自我实现：不是完美成功，而是更真实地成为自己', '马斯洛的自我实现不是外界眼中的完美人生，而是人的潜能、价值和创造力逐渐被活出来。它通常伴随更真实的自我接纳、更少迎合、更能投入当下、更愿意服务超出小我的价值。App 回答人生意义问题时，可引导用户从“我应该成为什么样”转向“什么让我更真实、更有生命力、更愿意贡献”。', '["自我实现", "真实自我", "意义感", "潜能", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 145, now()),
(100146, '高峰体验：短暂的完整感可以成为人生方向线索', '动机与人格中提到的高峰体验，可用于帮助用户回忆生命中短暂但强烈的完整、清明、感动或创造时刻。这些时刻不一定频繁，却能提示人的核心价值和潜能方向。App 可引导用户回忆：什么时候我感到特别真实、自由、宁静或被点亮？那里可能藏着比外部评价更可靠的成长线索。', '["高峰体验", "价值澄清", "生命力", "自我实现", "意义"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 146, now()),
(100147, '缺失性需要与成长性需要要区分', '缺失性需要来自匮乏，如缺安全、缺爱、缺尊重；成长性需要来自生命扩展，如创造、学习、贡献和理解。两者都重要，但处理方式不同。用户若在匮乏中追求成长，可能越努力越焦虑；若基础需求已相对稳定，却仍只追求补偿，也会感到空。App 可帮助用户判断：此刻我是在补缺口，还是在响应成长召唤？', '["缺失性需要", "成长性需要", "动机", "自我觉察", "人生阶段"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 147, now()),
(100148, '走出抑郁：抑郁会影响动机、注意力、睡眠和身体', '抑郁不仅是心情不好，它会影响动机、注意力、精力、睡眠、食欲、身体感和对快乐的体验。用户在抑郁状态下做不到平时能做的事，不应简单解释为懒或脆弱。App 回答时应把抑郁视为身心系统整体低能量状态，建议从睡眠、饮食、活动、支持和专业求助等多点恢复，而不是只靠一句“想开点”。', '["抑郁", "身心状态", "动机", "睡眠", "恢复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 148, now()),
(100149, '抑郁中的自责会加重抑郁循环', '抑郁状态下，人容易把精力下降、兴趣丧失、拖延和社交退缩解释成“我没用”。这种自责会进一步消耗能量，形成恶性循环。更有效的是把症状和身份分开：我现在处在低能量状态，不等于我没有价值。先减少自责，再做微小行动，才能逐步恢复掌控感。App 应帮助用户识别自责语言并改写为支持性语言。', '["抑郁", "自责", "自我价值", "支持性语言", "恢复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 149, now()),
(100150, '抑郁恢复需要活动计划，而不是等待心情变好', '走出抑郁的行为思路是：先安排可完成的小活动，再等待情绪慢慢回应。活动计划不必宏大，可从起床、洗漱、晒太阳、五分钟走路、整理一个角落开始。关键是可执行、可记录、可重复。用户若说“我没有动力”，App 可以回应：先不追求动力，先做一个小到可以完成的动作，让身体重新接触生活。', '["抑郁恢复", "活动计划", "行为激活", "小行动", "生活节律"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 150, now()),
(100151, '儿童绘画：画面是儿童表达情绪和经验的一种语言', '儿童绘画与心理治疗资料提醒，孩子常常无法直接用语言说出复杂感受，但会通过画面、颜色、大小、位置、重复主题和讲述方式表达经验。App 在亲子问题中可建议家长不要急着解释画得好坏，而是温和询问：“这是谁？发生了什么？你画这里时想到什么？”重点是让孩子讲述，而不是成人单方面解读。', '["儿童绘画", "儿童心理", "情绪表达", "亲子沟通", "治疗"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 151, now()),
(100152, '解读儿童画：不能只凭单个符号下结论', '儿童画不能机械解码，例如黑色就代表抑郁、画怪物就代表创伤。更可靠的方式是结合孩子年龄、发展水平、生活事件、绘画过程和孩子自己的讲述。App 若涉及儿童画，应避免下诊断，只提供观察方向：主题是否反复出现，孩子讲述时情绪如何，画面与近期事件是否相关，是否需要专业儿童心理支持。', '["儿童画", "非诊断", "观察", "儿童心理", "亲子"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 152, now()),
(100153, '儿童创伤表达：重复主题可能是在寻求理解和整合', '在儿童绘画治疗中，反复出现的危险、分离、攻击、受伤或孤独主题，可能是在尝试表达尚未被整合的经验。家长不应立刻责备“别画这些”，也不应过度惊吓，而要提供安全的讲述空间。可说：“你愿意讲讲这幅画里的故事吗？”如果孩子持续痛苦、退缩或行为明显变化，应考虑专业评估和支持。', '["儿童创伤", "绘画表达", "安全讲述", "亲子支持", "心理治疗"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 153, now()),
(100154, 'NLP过滤机制：误解常来自删减、扭曲与类推', '人在沟通中并不是原样接收现实，而会自动经过三类过滤：删减让人只注意部分信息；扭曲让事实被解释成批评、威胁或否定；类推会把一次经验扩展成“总是、从不、一定”。App 处理冲突时，可引导用户先做三问：我漏掉了哪些信息？还有哪些同样合理的解释？有没有反例说明这不是普遍规律？这样能把“对方就是针对我”降级为“我现在有一个解释，需要验证”。', '["NLP", "沟通模型", "删减", "扭曲", "类推", "误解修复", "提问"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 154, now()),
(100155, 'NLP表象系统：用对方能接收的感官通道组织语言', '不同人理解信息时偏好的通道不同：有人重“看见画面”，有人重“听到逻辑”，有人重“感觉是否踏实”，也有人依赖内在自我对话。沟通时不要只用自己习惯的表达方式，而要把关键信息翻译成多通道：画面是什么、听起来怎么说、身体或情绪感受如何、下一步怎么做。对方常用“看起来、听起来、感觉、我想”等词，可作为选择表达入口的线索。', '["NLP", "表象系统", "共同语言", "亲和感", "沟通表达", "感官通道"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 155, now()),
(100156, '小词汇审计：但是、试着、不要会悄悄改变行动暗示', '微小词汇会改变听者接收到的关系和行动暗示。“但是”容易否定前半句，可改成“同时/而且”；“试着”暗示困难和不确定，可改为具体承诺；“不要担心”会先唤起担心，可改成“先放松、先做第一步”；“这是很难的”把困难绝对化，可改成“我还没找到容易的方法”。App 生成沟通话术时，可加入小词汇审计，减少无意中的否定、无力和反向暗示。', '["语言风格", "NLP", "小词汇", "暗示", "沟通润色", "行动指令"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 156, now()),
(100157, '元程序沟通：先识别对方的动机过滤器，再选择说服入口', '影响他人不是把同一套理由重复给所有人，而是识别对方的“过滤器”：TA 更关注获得好处还是避免风险？喜欢选择空间还是固定程序？依据内部标准还是外部认可？更关心人、地点、活动、时间还是信息？同一个建议，对风险型用户要说明安全和代价，对机会型用户要说明收益和可能；对程序型用户给步骤，对选择型用户给选项。匹配元程序能降低理解阻力，但不能替代真实尊重。', '["NLP", "元程序", "影响力", "说服", "价值观", "职场沟通", "动机"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 157, now()),
(100158, '决策策略：把一次好决定拆成可复用的内在流程', '所谓策略，可以理解为一个人达成某个结果时反复使用的内在流程。面对选择困难时，不必只问“哪个更好”，可以回忆一次自己很满意的决定：当时先看见什么、听见什么、比较了哪些标准、想象了什么后果、身体如何确认、最后如何行动。把成功决策拆成步骤后，可形成个人模板；理解他人的决策策略，也有助于销售、谈判和关系协商。', '["NLP", "决策策略", "模拟卓越", "自我效能", "选择困难", "行为复制"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 158, now()),
(100159, '表达性写作的四个语言信号：情绪、意义与视角切换', '有帮助的书写不是单纯宣泄，而是把经历组织成可理解的故事。可关注四个信号：适度承认负面情绪，而非压住；出现积极情绪或希望线索；因果、理解、意义等认知词逐渐增加；人称代词能在“我、他人、我们”之间切换。App 可把书写提示设计成：发生了什么、我有什么感受、别人可能经历了什么、这件事说明了什么、下一步我能做什么。视角弹性越高，越不容易困在单一受害叙事里。', '["语言风格", "表达性写作", "书写疗愈", "视角切换", "情绪整理", "LIWC"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 159, now()),
(100160, '言语行为适切条件：承诺、道歉和命令都要满足关系规则', '一句话是否有效，不只看字面是否好听，还要看它是否满足适切条件：说话者是否有资格这样说，听者是否能理解，内容是否具体，意图是否真诚，后续义务是否清楚。空泛的“我以后会改”不是好承诺；没有承担影响的“对不起”也难以完成修复。App 生成承诺、道歉、请求话术时，应检查：具体行动、时间条件、能力边界、责任承担和复盘方式是否齐全。', '["言语行为", "承诺", "道歉", "请求", "关系规则", "沟通质量"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 160, now()),
(100161, '制度性事实：语言能创造责任、身份和共同规则', '有些事实不是自然发生的，而是由共同规则承认后才成立：承诺、任命、约定、道歉、家庭协议都属于这类语言创造的关系事实。两个人说“我们约好了”，只有在双方都理解条款、承认规则、知道后果时才真正有约束力。App 可把关系协商从口头情绪升级为共同规则：谁参与、约定什么、何时执行、如何检查、违反后如何处理。', '["言语行为", "制度性事实", "规则", "责任", "家庭协议", "关系协商"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 161, now()),
(100162, '太空时间：亲子危机时先开辟无追责的连接窗口', '当亲子关系已经出现明显隔膜时，可预先约定“太空时间”：在这段时间里暂停算旧账、讲道理、谈判和追责，只表达关怀、支持、真实感受和连接需求。它最好在平时心情好时建立规则，危机时双方都可以提出启动，一般不少于 30 分钟。关键不是放弃规则，而是先防止关系断线；家长若继续批判、否定、居高临下，这个技巧会失效。', '["亲子沟通", "太空时间", "关系修复", "情绪安全", "家庭冲突", "连接"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 162, now()),
(100163, '家中规则合约：少量、明确、可复述，规则才有教育力', '孩子不守规则，常不是故意挑战，而是规则太多、太模糊、没有解释清楚，或家长自己执行不一致。有效规则应少量优先，可先限制在七条以内；用具体行为替代抽象要求，如“晚上 9 点前完成作业”比“早点做完”更清楚；让孩子复述规则，确认理解；家长也要遵守相同规则或解释例外。规则越清楚，惩罚越少；爱和规则需要同时存在。', '["亲子教育", "家庭规则", "边界", "一致性", "规则合约", "温和坚定"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 163, now()),
(100164, '家庭会议五步骤：把家庭问题从互相责怪变成共同解决', '家庭问题反复出现时，可用会议流程替代临场吵架：第一，用正面、简短、无责怪的语言确定问题；第二，先收集多个方案，不急着批评；第三，讨论每个方案的可行性和每个人的感受，选出都能接受的方案；第四，分配行动和支持方式；第五，约定复盘时间，检查满意度。家庭会议应在情绪平稳时练习，它不削弱家长权威，反而训练孩子的问题解决能力。', '["家庭会议", "亲子沟通", "共同解决问题", "家庭系统", "冲突修复", "协商"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 164, now()),
(100165, '检定语言模式：从表层话语追问出深层限制', '用户说出的只是表层结构，背后常有删减、模糊和限制性信念。比如“我希望会变好”可能隐藏无力感，“我应该”可能隐藏外部压力，“我不能”可能缺少具体障碍说明。App 不宜急着给建议，而应先检定：具体是谁、什么情境、怎么知道、什么阻止了你、有没有例外、你真正选择什么？把“希望、应该、不能”转成“我选择、我会、我能先做哪一步”，能恢复用户的行动感。', '["NLP", "检定语言模式", "深层结构", "提问", "信念松动", "沟通澄清"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 165, now()),
(100166, '添增力量：先找出问题行为提供了什么力量', '一些不良行为并不只是“坏习惯”，也可能在临时提供力量：愤怒给人支撑，成瘾给人镇定，暴食给人安全感，控制给人掌控感。若只要求停止，用户会失去原本借来的力量。更好的顺序是：识别行为满足的力量需求；寻找更低代价的替代资源；调用过去成功经验、榜样角色或新的支持性信念。改变不是拿走拐杖，而是先让人重新站稳。', '["NLP简快疗法", "资源取向", "自我价值", "问题行为", "正向功能", "行为替代"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 166, now()),
(100167, '倾听障碍清单：识别自己是在听，还是在准备反应', '很多“我在听”其实是假倾听：对比自己、猜测对方意图、在脑中演练反驳、只听想听的部分、急着评判、好为人师、争辩挖苦、转移话题或一味讨好。App 可在冲突建议中先做倾听检查：我能否复述对方事实？我是否听见了情绪？我是否已经在准备反击？在回应前先复述并确认，能显著降低防御。', '["人际沟通", "倾听障碍", "主动倾听", "共情", "冲突降温", "复述"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 167, now()),
(100168, '弦外之音：声调、语速和重音会泄露真实关系态度', '话语的伤害不总在字面，常在辅助语言里：音高、语速、音量、停顿、重音和语调会传递自信、轻蔑、不耐烦、犹豫或优越感。内容上说“我当然支持你”，如果重音和语气带着讽刺，听者接收到的可能是否定。App 生成沟通脚本时，除了文字，还应提示语气：慢一点、低一点、停顿确认、避免反讽重音；同时提醒用户检查自己的真实目的是否与表达一致。', '["人际沟通", "辅助语言", "弦外之音", "语气", "非语言沟通", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 168, now()),
(100169, '人格理解：同一个人可以被多个流派同时照亮', '人格心理学不只提供一种解释，而是用多镜头理解人：精神分析关注无意识、防御和早期经验；特质流派关注稳定差异；生物学流派关注遗传、气质和脑机制；人本主义关注价值、成长和真实自我；行为主义和社会学习关注环境、强化和观察学习；认知流派关注图式、解释和自我调节。App 回答人格问题时，不宜把用户归入单一标签，而应根据问题选择镜头：这是关系脚本、长期特质、情境学习、身体反应，还是信念解释在起作用？', '["人格心理学", "多流派", "特质", "认知", "人本主义", "行为学习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 169, now()),
(100170, '大五人格：用于描述倾向，不用于决定命运', '大五人格可以帮助用户描述自己在开放性、尽责性、外向性、宜人性和神经质等维度上的相对倾向，但它不是命运判决。高神经质不等于注定痛苦，低外向不等于社交失败；特质只是“更容易怎样反应”的概率，不等于“只能怎样生活”。App 使用人格维度时，应把结论转化为策略：高敏感者设计恢复空间，低尽责者使用外部结构，高外向者注意深度连接，低宜人者练习表达关心。', '["大五人格", "特质", "自我理解", "成长策略", "非标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 170, now()),
(100171, '特质与情境：解释行为要同时看人和场景', '人格讨论常陷入两种极端：一种认为行为全由性格决定，另一种认为人只是被环境推着走。更实用的理解是，行为来自特质与情境的互动：同一个谨慎的人在安全关系中会更开放，同一个外向的人在高风险场合也会沉默。App 分析用户或伴侣行为时，应追问：这是长期稳定倾向，还是某个场景触发？若换时间、关系、压力水平和奖惩环境，行为会不会变化？', '["特质情境", "行为解释", "人格", "关系分析", "情境触发"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 171, now()),
(100172, '自我效能感：改变从“我能做一点”开始', '社会认知理论强调，人对自己能否完成行动的判断，会影响是否开始、坚持多久以及遇到挫折后如何恢复。自我效能感不是空喊自信，而是来自可重复的小成功、榜样示范、他人支持和身体状态改善。App 处理拖延、焦虑或关系修复时，可把目标缩小到一个可完成动作，并记录成功证据；当用户说“我不行”，应帮助改写成“我现在能先完成哪一小步”。', '["自我效能", "社会认知", "小成功", "行为改变", "自我调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 172, now()),
(100173, '自我图式：人会用熟悉的自我故事筛选信息', '认知流派提醒，人不是被事件本身直接决定，而是会通过自我图式解释事件。若用户带着“我不被喜欢”的图式，普通延迟回复也可能被理解为拒绝；若带着“我必须完美”的图式，小失误也会变成自我否定。App 可引导用户把自我故事拿出来检验：我现在用的是什么标签？它让我忽略了哪些证据？有没有一个更宽的自我描述能容纳缺点、努力和变化？', '["自我图式", "认知流派", "自我故事", "关系误读", "信念检验"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 173, now()),
(100174, '主体间性：痛苦常在关系场中形成，也要在关系中被理解', '主体间性心理治疗把来访者和咨询师看作共同构成的关系系统。人的感受并非孤立存在，而是在特定关系、文化、历史和互动方式中被组织出来。App 回答关系创伤、亲密恐惧或咨询相关问题时，可避免把痛苦完全归因于个人缺陷，而是帮助用户看见：我在什么关系场里形成了这种反应？当前互动如何重新激活旧经验？新的关系经验如何支持我重新组织自我感？', '["主体间性", "关系系统", "心理治疗", "经验组织", "关系创伤"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 174, now()),
(100175, '情感协调：先让对方感到被理解，再推动改变', '主体间取向强调，情感协调不是简单复述，而是治疗师或倾听者努力贴近对方当下主观体验，并把理解以可接收的方式反馈出来。很多人并不缺道理，而是缺“我的感受被准确看见”的经验。App 生成安慰或咨询式回应时，应先命名可能的感受、承认其处境意义，再进入建议；过早分析、纠正或教育，会让对方更孤独。', '["情感协调", "共情", "倾听", "关系修复", "心理咨询"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 175, now()),
(100176, '共情内省式倾听：理解对方的内在逻辑，而不是抢着解释', '共情内省式倾听要求倾听者暂时放慢自己的理论、评判和解决冲动，进入对方经验内部，理解其感受怎样在对方世界里成立。对 App 来说，这意味着先问“在你的处境里，这为什么会这么痛？”而不是先问“你为什么不换个想法？”当用户情绪强烈时，优先输出理解、澄清和陪伴；当其稳定后，再提供解释、练习和行动建议。', '["共情内省", "倾听模式", "心理咨询", "情绪支持", "理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 176, now()),
(100177, '治疗关系修复：断裂本身也可以成为新的经验', '关系治疗中难免出现误解、失望、距离或冲突。主体间视角不把这些断裂只看作失败，而是把它们视为共同理解旧模式和创造新经验的机会。App 在关系修复建议中可引导用户：发生了什么断裂？各自怎样理解？它触发了什么旧感受？现在能否用更安全、更直接的方式谈论？修复不是证明谁对谁错，而是让关系有机会承载真实感受。', '["关系修复", "治疗关系", "主体间性", "断裂修复", "真实表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 177, now()),
(100178, '抑郁认知三元素：自己、世界和未来同时变暗', '贝克抑郁理论把抑郁中的认知核心概括为三类负性模式：用负性方式看自己，觉得自己无价值或有缺陷；用负性方式看世界，觉得环境充满剥夺、失败和阻碍；用负性方式看未来，觉得情况不会改善。App 遇到抑郁倾向表达时，可帮助用户把“事实”与“抑郁滤镜”区分开：这是我全部的人生，还是低落状态下被激活的一套解释？', '["抑郁", "贝克认知理论", "负性认知", "自我世界未来", "认知滤镜"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 178, now()),
(100179, '抑郁症状要分层看：情绪、认知、动机和身体会互相牵连', '抑郁不是单一情绪问题，常同时表现为情绪低落或空洞、负性自我评价、注意和思维迟缓、做事动力下降、回避、睡眠食欲和身体能量变化。App 回答时应避免把用户简单归为“懒、玻璃心、想太多”，而要提示这是一个身心系统状态。更有效的恢复路径通常需要多点介入：规律作息、微小活动、认知检验、关系支持和必要的专业帮助。', '["抑郁症状", "情绪", "认知", "动机", "身体反应", "恢复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 179, now()),
(100180, '抑郁图式：旧的负性模板会在压力下被重新激活', '抑郁易感性可以理解为某些负性图式在压力下被激活。平时用户可能还能维持功能，但在失恋、失败、丧失、冲突或长期压力下，旧模板会把事件解释成“我不够好、我会失去、未来没希望”。App 可帮助用户识别激活点：最近发生了什么压力？它碰到了哪种核心信念？有没有证据说明这只是旧模板，而不是全部现实？', '["抑郁图式", "压力触发", "核心信念", "认知易感性", "反刍"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 180, now()),
(100181, '反刍会放大抑郁：重复想不等于真正解决', '抑郁状态下，人容易反复咀嚼同一件事，以为想清楚才能行动，但反刍常让注意力越来越窄、情绪越来越重、行动越来越少。App 可以把反刍和问题解决区分开：反刍是循环问“为什么我这么糟”，问题解决是写下可验证事实、可影响部分、下一步行动和需要支持的人。若思考超过一定时间仍只增加痛苦，就应转向身体活动、外部支持或具体任务。', '["反刍", "抑郁", "问题解决", "注意力", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 181, now()),
(100182, '抑郁复发预防：恢复后仍要维护认知和生活系统', '抑郁好转不等于风险完全消失，维持治疗、认知练习和生活结构能降低复发概率。App 可把复发预防做成日常清单：睡眠和活动是否稳定？是否又开始孤立？是否出现“我没用、没希望”的自动解释？是否停止了有效练习？是否有可以提前联系的支持对象？重点是早识别、早调整，而不是等到完全崩溃才求助。', '["抑郁复发", "维持治疗", "认知疗法", "生活结构", "早期预警"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 182, now()),
(100183, '把信念当假设：用小实验替代空想式显化', '《能量》类资料适合被 App 转译成自我觉察练习：不要把“意念创造现实”理解成逃避现实责任，而是把信念当作可检验假设。若用户相信“没有机会”，可以设计一个 48 小时小实验：主动寻找三个机会线索、记录自己忽略了什么、采取一个微行动。这样把抽象信念落到注意力、选择和行动上，既保留积极探索，也避免陷入空想。', '["能量练习", "信念实验", "注意力", "积极心理", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 183, now()),
(100184, '注意力会筛选现实：你寻找什么，就更容易看见什么', '人每天接触的信息远远超过能处理的范围，因此注意力会像过滤器一样选择哪些线索进入意识。当用户长期只寻找威胁、缺失和失败，大脑会不断证明“世界就是这样”；当用户练习寻找资源、支持和可行动线索，也会更容易看见新的可能。App 可引导用户做注意力复盘：今天我自动看见了什么？我忽略了什么？如果我寻找一个微小资源，会在哪里？', '["注意力", "选择性知觉", "资源取向", "积极练习", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 184, now()),
(100185, '感恩不是否认问题，而是训练大脑看见已拥有的资源', '感恩练习的价值不在于粉饰困难，而在于让用户从“我只有缺口”的单一叙事中恢复平衡。有效感恩要具体：今天谁提供了支持？我完成了哪件小事？身体还在支持我什么？环境里有什么可用资源？App 在低落或匮乏感问题中，可建议用户每天记录三项具体资源，并配合一个现实行动，让感恩连接到力量，而不是变成压抑情绪的口号。', '["感恩", "资源觉察", "积极心理", "匮乏感", "低落恢复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 185, now()),
(100186, '疯传 STEPPS：传播不是运气，而是六类心理机制叠加', '《疯传》提出，内容和行为更容易传播，往往不是因为广告预算最大，而是触发了六类机制：社交货币让分享者显得有价值；诱因让人被环境反复提醒；情绪唤醒推动转发；公开可见让模仿更容易；实用价值让人愿意帮别人；故事把信息包装进可复述情节。App 可把这套框架用于课程、活动和内容传播诊断：缺哪一环，就补哪一环。', '["疯传", "STEPPS", "传播心理", "影响力", "内容策略", "社交货币"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 186, now()),
(100187, '社交货币：用户分享的不是内容，而是分享后的自我形象', '人们愿意分享能让自己显得聪明、有品位、有内部消息、乐于助人或与众不同的内容。传播设计不应只问“我们想说什么”，还要问“用户转发后会显得怎样”。App 可用于内容建议：给用户一个可展示的洞察、身份、成就或独特表达，让分享行为成为自我形象的一部分；但社交货币必须和真实价值相连，否则会变成噱头。', '["社交货币", "内容传播", "身份表达", "用户分享", "影响力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 187, now()),
(100188, '诱因：把想传播的行为绑定到高频场景', '好内容如果没有被想起的触发点，也容易沉下去。诱因的关键是把信息绑定到用户日常会频繁遇见的场景、词语、时间和动作上：一到周一想到复盘，一看到咖啡想到能量，一遇到冲突想到暂停三问。App 可帮助课程和产品设计触发器：用户什么时候最需要这条知识？现实中什么线索会提醒 TA？如何把提醒嵌入日常而不是只靠一次宣传？', '["诱因", "触发器", "习惯场景", "内容传播", "行为设计"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 188, now()),
(100189, '高唤醒情绪更容易推动传播，但要服务真实价值', '不是所有情绪都同样推动传播。高唤醒情绪，如惊讶、敬佩、愤怒、焦虑、兴奋，更容易促使人行动；低唤醒情绪，如满足或悲伤，未必带来同样的转发动力。App 生成传播建议时，可帮助用户寻找内容中的情绪核心：它让人惊讶在哪里？敬佩什么？担心什么？但情绪唤醒不等于煽动，最好让情绪服务于理解、行动和真实帮助。', '["情绪传播", "高唤醒", "内容策略", "影响力", "行动动力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 189, now()),
(100190, '实用价值：越具体、越省力、越能帮到别人，越容易被转发', '人们常分享有用信息，因为这让他们能帮助别人、维持关系并展示判断力。实用价值要具体：省多少钱、少踩什么坑、按哪几步做、适合谁、不适合谁。App 可把知识库内容改写成可传播建议：标题直接说用途，正文给步骤和场景，结尾给转发对象。抽象鸡汤不如一个清晰清单，模糊道理不如一个今天就能用的小工具。', '["实用价值", "清单化", "内容传播", "帮助他人", "行动步骤"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 190, now()),
(100191, '故事是信息的运输工具：让观点藏在可复述情节里', '故事能传播，是因为人们更愿意复述人物、冲突、转折和结果，而不是背诵抽象观点。一个好故事应让核心信息不能被轻易剥离：如果用户讲完故事却忘了产品、课程或方法，说明信息没有嵌入情节。App 可建议内容创作者用“人物遇到什么困境—尝试什么方法—发生什么转变—听众能带走什么行动”来组织表达，让知识随故事一起被记住。', '["故事传播", "叙事", "内容策略", "知识表达", "可复述"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 191, now()),
(100192, '人格测验的信度与效度：分数只能作线索，不能作判决', '人格测验要先问两件事：信度，即同一测验能否稳定、一致地测到某种倾向；效度，即它测到的东西是否真是想测的建构。高信度不等于高效度，一个量表可能稳定地测到“社会赞许倾向”而不是自尊。自陈量表还会受到伪装、敷衍答题、阅读理解、反应倾向和测评动机影响。App 解读测评结果时，应提醒：结果适合作为自我观察、讨论和后续行为验证的起点，不适合单凭一个分数判断人格、诊断障碍、录用或淘汰某人。更可靠的做法是结合长期行为、他人反馈、情境记录、功能损害和专业评估。', '["人格测验", "信度", "效度", "自陈量表", "测评解读"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 192, now()),
(100193, 'DSM-5替代性模型：人格障碍评估从类别转向功能画像', '人格障碍不宜只用“是不是某型”理解。维度化模型把重点放在两类信息：人格功能受损和病理性人格特质。人格功能包括身份认同、自我定向、共情、亲密等自我与人际能力；病理特质则描述消极情绪、疏离、对抗、脱抑制、精神质等方向的程度。这样能把人格问题放到连续体上看：普通人也会有某些特质，只是强度、僵化度、跨情境稳定性和功能损害不同。App 适合用作非诊断回答：先评估长期性、跨场景、功能损害、自我/人际能力，再讨论边界、求助和干预，而不是给用户或他人贴临床标签。', '["人格障碍", "DSM5", "维度模型", "人格功能", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 193, now()),
(100194, '图式—模式—策略：人格障碍的认知行为底层模型', '认知行为视角把人格障碍理解为“图式—模式—策略”的持续循环。图式是关于自我、他人和世界的深层信念；模式是某些图式在特定情境下被整体激活后的认知、情绪、动机和行为状态；策略原本有适应意义，如寻求安全、保持自主、争取认可、避免伤害，但当它过度发展、发展不足或僵化使用时，就会制造持久的人际和自我功能问题。干预不是简单纠正错误想法，而是先看策略保护了什么，再通过关系体验、行为实验、图式反馈、正念或角色扮演，让人发展更灵活的新策略。', '["人格障碍", "CBT", "图式", "模式", "行为策略", "个案概念化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 194, now()),
(100195, '人格障碍治疗联盟：关系本身就是行为实验室', '人格障碍干预比症状干预更依赖治疗联盟，因为改变慢、挫败多，且来访者的核心信念常会在治疗关系中被激活：害怕被拒绝、被控制、被羞辱、被利用，或觉得必须取悦/反抗治疗师。有效工作不是只讲技术，而是把关系困难纳入概念化：发生误解时及时标记，鼓励具体反馈，治疗师保持非防御态度，把会谈中的回避、顺从、攻击、理想化或贬低视为可观察材料。App 可借鉴这一点：面对高度敏感或长期模式用户，先建立可预测、尊重边界的互动，再引导事实记录、情绪稳定和小步实验。', '["治疗联盟", "人格障碍", "治疗关系", "CBT", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 195, now()),
(100196, '回避型人格模式：安全行为会短期降焦虑、长期困住自我', '回避型模式的核心不是“不想关系”，而是“渴望关系但预期羞辱、批评、拒绝”。回避、沉默、提前退出、不表达真实需求、只给正面反馈等安全行为，短期能降低焦虑，却让人失去验证新经验的机会，长期强化“我无法承受他人评价”的信念。认知行为干预强调：先建立足够安全的关系，再识别回避链条，逐步暴露于可承受的社交风险，练习自信表达、负面反馈、情绪耐受和行为实验。App 可把“逃开”翻译成保护策略，同时帮助用户设计低风险的接近练习。', '["回避型人格", "安全行为", "社交焦虑", "行为实验", "情绪耐受"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 196, now()),
(100197, '自恋型人格的认知理解：脆弱自尊与特权策略并存', '自恋模式不只是“自大”，更常是脆弱自尊与补偿性优越感的组合。个体可能把价值感建立在特殊、卓越、被认可之上，因此对批评、忽视、失败或地位受损高度敏感；当自尊受威胁时，容易使用贬低他人、要求特殊待遇、回避羞耻、争夺控制等策略。App 回答时不宜用“自恋”骂人，而应拆成可观察模式：是否需要持续赞美，是否难以承认影响，是否把普通反馈理解为羞辱，是否通过控制关系维持自尊。对当事人可引导区分真实自我价值与外部评价，练习承担影响而不崩塌。', '["自恋型人格", "自尊", "羞耻", "关系模式", "认知治疗"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 197, now()),
(100198, '偏执型人格模式：威胁扫描会把保护策略变成关系破坏', '偏执型模式可以理解为保护策略过度化：个体高度关注被伤害、被侵犯、被欺骗或被控制的可能，倾向把模糊信息解释成针对自己的威胁。它的短期功能是降低被动受害感，长期后果却是不断检查、质疑、反击和疏离，让他人更防御，反过来“证明”世界不可信。App 在关系咨询中可帮助用户把“对方一定有恶意”改写为可检验假设：事实是什么、还有哪些解释、若保持边界但暂缓攻击会怎样。面对他人的偏执化互动，则强调安全、边界、书面事实和避免陷入辩解循环。', '["偏执型人格", "威胁解释", "保护策略", "关系边界", "认知重评"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 198, now()),
(100199, '超越性动机与存在价值：成长后期需要比“我”更大的方向', '在基本需要相对稳定后，人仍可能感到空洞，因为动机不只包括补缺口和实现个人潜能，还包括对真、善、美、创造、意义、整体性、正义、卓越等存在价值的回应。马斯洛晚期把这类更高动机称为超越性动机或超越性需要：人需要献身于某种大于个人欲望的对象，突破只以自我利益为中心的生活。App 可在用户问“为什么条件不错仍空虚”时引导：先确认基础需求与心理困扰，再探索哪些价值让他愿意服务、学习、创造、守护或奉献。它不是道德绑架，而是成熟人格的方向感来源。', '["马斯洛", "超越性动机", "存在价值", "意义感", "成长需要"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 199, now()),
(100200, '九型心理缓冲带：防御机制会遮住类型真相', '九型资料把“心理缓冲带”理解为人为了维持自我形象而形成的防御系统。它会把性格中的负面特征、羞耻和矛盾挡在意识之外，使人只看到自己愿意相信的版本。不同类型常有不同防御倾向，如反向作用、压抑、认同、内投、分隔、投射、合理化、否定、麻醉等。RAG 中这比“测出我是几号”更有价值：识别类型时看一个人如何维护自我感、怎样解释冲突、哪些反馈最难听进去。成长不是撕掉防御，而是在安全和诚实中看见它保护的脆弱需要。', '["九型人格", "心理防御", "自我观察", "类型识别", "成长练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 200, now()),
(100201, '九型潜藏激情：类型背后的情绪习性比行为更关键', '九型人格的“激情”指反复劫持注意力的情绪习性，不是偶发情绪。它们可被看作早期适应留下的阴影：当某种情绪习惯被点燃，人会围绕它组织解释、关系和行动，并失去自我观察能力。判断类型时，不只看外在行为，而要看注意力最容易被什么情绪主题牵引：愤怒、骄傲、形象、嫉羡、匮乏、恐惧、贪多、控制、怠惰或麻木等。App 可引导用户记录“我在冲突中最自动的情绪剧本是什么”，再把激情当成返回真实需要和失落品质的线索。', '["九型人格", "潜藏激情", "注意力", "情绪习性", "类型成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 201, now()),
(100202, '情绪工作五项底层技能：接地、边界、引导、抱怨与复原', '强烈情绪不是只靠理解就能处理。先把自己带回身体和当下，再给内在体验划出边界，才更容易安全地翻译情绪。可作为五步框架：1）接地：借呼吸、身体感、脚下支撑，让情绪流过而不被淹没；2）定义边界：用愤怒、羞耻等信号辨认“我与他人”的界线；3）负责任地引导情绪：不压抑、不乱发泄，找安全容器表达；4）有意识地抱怨：把怨气从攻击变为看见未满足需要；5）恢复自我活力：情绪过后回到资源、节律和行动。适合回答“情绪上来怎么办”“如何不被情绪吞没”。', '["情绪语言", "情绪调节", "接地", "边界", "身体觉察", "自我复原", "强烈情绪"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 202, now()),
(100203, '情绪亲密的三层共情：感觉到、同情、同感都需要边界', '与人共情不是越融合越好。情绪亲密可分三层：感觉到，是用身体临在、表情、语调和细节读取对方状态；同情，是在心的层面与对方相连，让对方感到安全和被理解；同感，是双方在共享情绪中并肩共振。风险也随层级增加：只“感觉到”可能变成旁观或操控；“同情”过度会吸收太多、丢失自己；“同感”失衡会形成封闭的“我们”而拒绝反馈。健康共情=连接+自主+可质疑，适合亲密关系、咨询倾听和团队情绪支持。', '["情绪亲密", "共情", "同情", "同感", "边界", "倾听", "关系安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 203, now()),
(100204, '愤怒两步公式：痛苦或压力遇到触发思维才会点燃', '愤怒常由两部分组成：先有身体或情感上的痛苦/压力，如疲劳、头痛、被拒绝、需要受阻；随后出现触发思维，把情境解释为“对方故意伤害我、冒犯我、应该受惩罚”。痛苦像燃料，触发思维像火柴；任一部分被看见，愤怒链条就有机会中断。RAG 可用于生成愤怒日志字段：压力源、客观事件、触发解释、愤怒强度、实际行为、对自己后果、对他人后果。干预重点是同时降低生理唤醒和替换指责、灾难化、支配性想法。', '["愤怒管理", "触发思维", "压力", "认知扭曲", "愤怒日志", "身体唤醒"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 204, now()),
(100205, '愤怒的隐藏奖赏：短期奏效会强化爆发', '有些愤怒难改，不是因为当事人不知道它伤人，而是因为它短期内“有用”：别人退让、停止要求、改变安排，自己获得控制感和释放感。这种奖赏会把愤怒训练成默认工具，即使长期代价是关系疏远、抵抗升级和自责。反愤怒方案要问三件事：这次爆发带来了什么积极结果？我真正想保护的需要是什么？有没有不破坏关系也能达成同样结果的方式，如坚定表达、协商、设置容忍度、独立制定计划。适合处理“我知道发火不好但忍不住”。', '["愤怒强化", "控制感", "边界表达", "替代行为", "协商", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 205, now()),
(100206, '抑郁中的自我批评：评估行为，不审判整个人', '自我批评在抑郁中常从“我这件事没做好”滑向“我这个人不行”。把成绩、考试、家务、工作等结果绑定到“我”的价值，会让失败变成自我攻击。更有帮助的区分是：行为可以复盘，结果可以失望，策略可以调整，但人的基本价值不随一次成败升降。走出抑郁需要两种思维协作：理性思维像侦探，检查证据、寻找多种解释、做小实验；同情性思维像可靠照护者，用友好、支持、宽恕和修复取代威胁惩罚。适合自责、羞耻、完美主义引发的抑郁检索。', '["抑郁", "自我批评", "自我价值", "同情性思维", "理性思维", "羞耻"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 206, now()),
(100207, '抑郁康复的共同照护：研究自己的模式并预设求助信号', '康复故事反复指向一个实用原则：来访者不是被动等待治疗，而要逐渐成为自己康复系统的共同管理者。做法包括：记录自己的发作模式和季节/生活事件触发点；观察睡眠、饮食、精力、语速、退缩、冲动等早期信号；把有效疗法、药物、运动、互助、日记、光照、饮食等整理成个人方案；提前授权可信亲友在发现异常时联系医生或治疗师。它不是“靠自己硬扛”，而是把自我觉察、专业支持和社会支持制度化，让低谷时仍有人能拉响警报。', '["抑郁康复", "自我监测", "支持系统", "早期信号", "治疗合作", "生活方式"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 207, now()),
(100208, '拖延三管齐下：改写思维、锻炼情绪肌肉、用五分钟启动', '拖延不是单纯懒惰，而是认知、情绪、行为连锁：任务出现负面看法，引发焦虑、厌恶或压力，再用低压力活动替代，获得即时放松，拖延因此被强化。反拖延可三管齐下：认知上识别“以后再做、准备好再开始、失败就完了”等拖延思维，把计划看成可检验假说而非人格审判；情绪上练“情绪肌肉”，接纳不适、观察身体紧张，放弃短期逃避换长期收益；行为上用五分钟计划，先承诺开始五分钟，再决定下一个五分钟。适合任务启动困难和压力型拖延。', '["拖延", "三管齐下", "情绪肌肉", "五分钟计划", "认知改写", "行动启动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 208, now()),
(100209, 'TA 的认可饥渴：人际游戏常在替代真实亲密', '沟通分析把人际互动看成满足三种基本渴望的方式：刺激渴望、认可渴望和结构渴望。婴儿需要身体抚触，成人也需要象征性“安抚”，如问候、微笑、回应和被看见；但仅有问候不够，人还需要安排清醒时间，于是活动、仪式、消遣、游戏、亲密成为不同层级的时间结构。心理游戏之所以顽固，是因为它既提供认可和时间结构，又避免真实亲密的脆弱。App 可据此区分：用户是在寻求真实请求、普通消遣，还是通过反复冲突获取安抚。', '["沟通分析", "认可饥渴", "安抚", "时间结构", "心理游戏", "亲密"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 209, now()),
(100210, 'TA 三类沟通：互补维持互动，交错制造中断，隐藏形成游戏', '在沟通分析中，一次沟通不只看说了什么，还看由哪个自我状态发出、邀请对方哪个自我状态回应。互补沟通指刺激和回应方向匹配，互动能顺利继续；交错沟通指回应来自意料之外的自我状态，谈话容易卡住、冲突或转向；隐藏沟通则同时存在社交层和心理层，表面像理性对话，底层却在交换依赖、控制、惩罚、讨好或逃避。心理游戏常是隐藏沟通反复运行并导向可预测结局。适合解析“明明只是小事却总吵起来”的对话结构。', '["沟通分析", "互补沟通", "交错沟通", "隐藏沟通", "自我状态", "冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 210, now()),
(100211, '人际游戏公式：骗局、弱点、回应、转换和结局', '心理游戏不是简单“耍心机”，而是习以为常但功能不良的安抚方式。G 公式可作为识别模板：一方抛出看似合理的刺激或骗局；对方的弱点被勾住并回应；随后发起者或参与者自我状态转换；最后出现熟悉的情绪结局，如正义愤怒、委屈、被踢、无助。戏剧三角补充说明角色会在受害者、拯救者、迫害者之间快速互换。退出游戏的关键不是争输赢，而是识别隐蔽动机、拒绝接预设角色、把沟通拉回真实请求和可协商边界。', '["人际游戏", "G公式", "戏剧三角", "受害者", "拯救者", "迫害者", "沟通分析"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 211, now()),
(100212, '主体间场：治疗师不是旁观者，而是共同创造治疗环境的人', '主体间心理治疗把咨访关系看成由两个主体共同形成的系统。治疗师对来访者主观经验的理解，会受到治疗师自身主体性、理论假设、文化背景、情绪反应和经验组织方式影响；这些影响不是要被假装消除，而是要被敏感地觉察和使用。治疗环境也不是固定容器，而由场所、共情倾听、互动关系以及不可预知的双方经历共同创造。RAG 可用于提醒咨询师：解释来自关系背景，任何“客观看法”都要检查自己在主体间场中的贡献。', '["主体间场", "咨访关系", "治疗师主体性", "共同创造", "反思", "心理治疗"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 212, now()),
(100213, '情感协调的治疗力：破裂—修复和特殊情感时刻会重组经验', '主体间治疗强调经验围绕情感组织，因此改变情感体验会为新的经验组织打开机会。婴儿研究提供了三个关键原则：互动中的持续调节、破坏与修复、特殊情感时刻。迁移到心理治疗中，来访者与治疗师会共同期待、误会、调整和修复；当某一刻来访者真实感到“我的体验被另一个人感受到并适当回应”，就可能扩大自我调节范围，形成新的共享情感经验。它解释了为什么一次真诚的理解、一次关系裂痕后的修复，有时比完美解释更有治疗作用。', '["情感协调", "破裂修复", "特殊情感时刻", "自我调节", "主体间性", "治疗关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 213, now()),
(100214, '霍妮三种人际移动：亲近、对抗、疏远都是求安全', '霍妮把许多内心冲突理解为三种人际方向的拉扯：亲近他人时，用户可能用讨好、依赖、牺牲来换安全；对抗他人时，可能用控制、竞争、证明自己来避免被伤害；疏远他人时，可能用冷淡、消失、自给自足来保住自主。App 端回答时，不宜只把这些反应评价为“太软弱”“太强势”或“太冷漠”，而要追问：我此刻在防什么危险？我最怕失去的是爱、价值、尊严还是自由？成熟不是固定选择某一种策略，而是在不同关系里能更有弹性地靠近、设限或退后。', '["霍妮", "内心冲突", "人际模式", "讨好", "对抗", "疏远", "安全感", "关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 214, now()),
(100215, '理想化自我与外化：假和谐会把冲突推远', '内在冲突常会被两种方式暂时盖住：一是制造一个“我应该永远优秀、正确、被喜欢”的理想化形象；二是在理想化破裂后，把痛苦完全外化为“都怪别人/环境”。前者让人不断羞耻和自责，后者让人短期舒服却远离可改变的部分。App 可帮助用户区分愿景与苛刻形象：我要求自己必须成为什么样才配被接纳？现实中哪一小部分是我能承担和调整的？哪一部分确实属于外部限制，需要边界、协商或资源支持？', '["霍妮", "理想化自我", "外化", "内耗", "羞耻", "责任", "自我接纳", "冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 215, now()),
(100216, '每日情绪日志：焦虑要写成可检验的想法', '焦虑自助不只是让用户“别想太多”，而是把脑内灾难化写成可检查的材料。可引导用户用每日情绪日志记录：触发事件是什么；焦虑、羞耻、愤怒等情绪各有多强；脑中自动想法是什么；其中有哪些放大、读心、非黑即白、应该化等认知扭曲；更平衡的回应是什么；重新评分后情绪是否下降。这样做的重点不是强迫积极，而是把“我完了”变成“这是一个想法，我能找证据、找替代解释、做小实验”。', '["焦虑", "认知疗法", "每日情绪日志", "认知扭曲", "自助", "想法检验", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 216, now()),
(100217, '暴露与行为实验：停止用回避喂养恐惧', '许多焦虑之所以持续，是因为回避让大脑一直没有机会更新：“我不去，所以没出事”会被误解为“幸好我不去，否则一定完蛋”。暴露不是鲁莽硬闯，而是把害怕情境拆成可承受的小阶梯：先写下预测的最坏结果和概率，再设计一次安全、具体、可停止的小实验，记录真实发生了什么。用于社交焦虑、羞怯、反复担忧时，App 可建议用户减少一个安全行为、完成一次低风险接触，再用结果修正旧信念。', '["焦虑", "暴露法", "行为实验", "回避", "安全行为", "社交焦虑", "信念更新"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 217, now()),
(100218, '认知不协调：改变观点常从小行为和自我辩解开始', '人做了与自我形象不一致的事，会产生不舒服的认知不协调，并倾向于通过改变态度或编理由来恢复一致感。关系沟通和行为改变中，与其强迫对方承认“你错了”，不如邀请一个低压力、可自愿的小行动，再让对方从行动经验中更新看法。反过来，用户也要警惕自己被承诺、沉没成本和公开表态绑住：我现在坚持，是因为证据更充分，还是因为不想承认之前的选择可能有问题？', '["认知不协调", "态度改变", "自我辩解", "承诺", "行为改变", "沟通", "社会影响"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 218, now()),
(100219, '社会学习：榜样、强化和环境比说教更能改行为', '社会学习视角提醒，行为常由观察、模仿、奖惩和自我期待共同塑造。亲子、伴侣或团队场景里，单纯说教和羞辱往往不如清楚示范、即时反馈和环境设计有效。App 可把建议落到三个问题：谁正在示范这种行为？这个行为之后立刻得到了什么奖励或代价？环境里哪些提示在鼓励旧模式？想培养新行为，就要让新行为更容易被看见、被做到、被肯定，而不是只要求对方“自觉一点”。', '["社会学习", "榜样", "强化", "环境设计", "行为改变", "亲子沟通", "团队管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 219, now()),
(100220, '旁观者效应：责任不明确时，善意会被群体稀释', '社会心理学中的旁观者研究显示，人越处在一群人中，越可能等待别人先行动；这不一定是冷漠，而常是责任扩散、彼此观望和误判情境造成的。App 在危机求助、团队协作或家庭分工中，可建议把“有没有人帮我”改成命名、限时、具体的请求：请 A 现在打电话，请 B 陪我去医院，请 C 今天 18 点前确认方案。明确责任能把模糊善意转化为行动，也能减少用户把无人响应解释成“我不值得被帮”。', '["旁观者效应", "责任扩散", "求助", "群体影响", "具体请求", "危机沟通", "社会心理学"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 220, now()),
(100221, '少数意见的价值：不同声音能防止群体迷思', '群体决策中，表面一致并不总是健康；少数意见会迫使群体更仔细检查证据，激发发散思维和创造力。若为了和气、效率或权威而压制异议，团队容易进入群体迷思：没人敢说风险，最后一起做出差判断。App 可建议家庭或团队设置“反方角色”：先收集不同意见，再决定；先讨论证据，再投票；特别询问沉默者看见了什么。关系质量不是没有分歧，而是分歧能被安全表达。', '["群体迷思", "少数意见", "团队决策", "发散思维", "异议", "心理安全", "社会心理学"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 221, now()),
(100222, '心理标签效应：诊断词会改变我们看见一个人的方式', '经典实验提醒，一旦给人贴上心理或人格标签，后续普通行为也容易被解释成标签证据。App 端应避免把“抑郁型人格、回避型、病态、自恋”等词当作判决书；更适合把标签降级为线索，并回到可观察事实：这种行为出现多久？在什么场景出现？带来什么功能损害？对方是否也有例外表现？对自我标签同样如此，“我就是废物/拖延人格”要改写为“我在某些任务前会回避，但可以观察触发点并练习下一步”。', '["心理标签", "诊断谨慎", "人格", "自我标签", "观察事实", "污名化", "心理实验"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 222, now()),
(100223, '思维定势与功能固着：换问题框架才能产生新选择', '人解决问题时常被既有用法和第一反应锁住，以为某个物品、角色或关系“只能这样”。思维定势会让用户在冲突中反复问“谁对谁错”，却忘了还可以问“我们真正要达成什么功能”。App 可引导用户拆框：我默认了哪些必须？这个资源除了原用途还能支持什么？如果目标不变、路径换三种，会有哪些选择？在亲密关系、职场沟通和自我改变中，创造力往往不是更用力，而是先松开旧框架。', '["思维定势", "功能固着", "创造力", "问题重构", "决策", "沟通", "心理实验"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 223, now()),
(100224, '社会建构视角：别把所有痛苦都解释成个人性格', '社会学视角强调，个人行为背后常有角色、规范、制度和文化脚本。用户把一切痛苦归因为“我太脆弱、我不够努力”时，App 可补问：这个家庭/单位/群体期待你扮演什么角色？哪些奖励和惩罚在维持当前模式？有没有阶层、性别、年龄、职业规则让选择变窄？这不是否认个人责任，而是避免把结构性压力伪装成性格缺陷。有效改变有时不是再逼自己，而是调整规则、边界、资源和支持网络。', '["社会学", "社会建构", "角色", "规范", "制度", "结构性压力", "自责", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 224, now()),
(100225, '成年发展的生态视角：人生危机常是角色与环境重组', '成年发展不是一条直线，也不只由年龄数字决定。人的困境会受实足年龄、生理年龄、心理年龄、社会年龄，以及时代、家庭、工作、健康和突发事件共同影响。App 回答“我这个年纪还这样是不是失败”时，可把羞耻改写为发展评估：我正在经历哪种角色转换？这个压力来自年龄常规事件、时代变化，还是非常规打击？我需要学习的新能力、支持系统和身份叙事是什么？这样能把危机从自我否定转为角色与环境重组。', '["成年发展", "生态视角", "人生阶段", "角色转换", "年龄", "身份", "支持系统"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 225, now()),
(100226, '改变难以坚持：洞见之后要搭建维持系统', '重大改变很少只靠一次顿悟完成。危机、故事、支持、治疗、旅行、意义感都可能触发改变，但旧环境和旧奖励会把人拉回原模式。App 在用户“我终于想通了”之后，应继续追问维持系统：未来最可能复发的场景是什么？谁能在我退回旧模式前提醒我？我要改变哪些环境提示？每周用什么仪式复盘？如果跌回去，最小恢复动作是什么？真正的改变不是永不反复，而是反复时有回到轨道的方法。', '["改变心理学", "复发预防", "维持系统", "洞见", "支持网络", "习惯保持", "行动计划"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 226, now()),
(100227, '影响力防身清单：好感、权威、稀缺和社会认同都要慢下来', '影响力原则既能帮助沟通，也可能劫持判断。用户在冲动购买、仓促承诺、关系让步或群体跟风前，可做防身清单：我是否因为别人先给了好处而急着回报？是否因为已公开承诺而不愿调整？是否因为大家都这样做就停止思考？是否把头衔、专业感或自信语气误当证据？是否被“最后机会、限量、错过就没了”推着走？健康的影响力应允许对方慢下来、看证据、保留拒绝权。', '["影响力", "互惠", "承诺一致", "社会认同", "权威", "稀缺", "决策", "防操控"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 227, now()),
(100228, '情感隐藏模型：焦虑有时是在替未表达的情绪站岗', '有些焦虑不只来自认知扭曲，也可能在保护某些“不方便表达”的情绪：不敢承认愤怒，于是变成担心；不敢说需要，于是变成反复控制；不敢面对悲伤，于是忙着焦虑未来。App 不应把所有焦虑都机械套入“想法错了”，也可以温和询问：如果焦虑暂时停下，底下最可能浮现什么感受？我有什么请求、边界或哀伤一直没被说出口？当隐藏情绪被安全表达，焦虑有时会自然下降。', '["焦虑", "情感隐藏", "情绪表达", "需要", "边界", "认知疗法", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 228, now()),
(100229, '确认性偏见：主动寻找反证，才能突破自我证明循环', '确认性偏见会让人更容易看见支持自己观点的信息，并忽略挑战自己信念的证据。关系冲突中，用户若先认定“TA 不在乎我”“我一定会失败”，后续所有细节都可能被筛选成证据。App 可引导用户做反证练习：如果我的判断错了，会有哪些迹象？有哪些事实同时支持另一种解释？我能不能问一个开放问题，而不是继续搜集控诉材料？真正的理性不是永远相信自己，而是愿意让信念接受检验。', '["确认性偏见", "反证", "认知偏差", "关系误读", "自我觉察", "开放问题"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 229, now()),
(100230, '后知之明偏见：复盘时不要把结果倒推成“早就知道”', '事情发生后，人很容易觉得结果本来就显而易见，并低估当时的不确定性。后知之明偏见会让复盘变成责备：你明明早该看出来、我怎么这么笨、早知道就好了。App 可把复盘改成过程复盘：当时我掌握了哪些信息？哪些风险是真能看见的，哪些是事后才知道的？下一次可设置什么预警信号？这样既保留学习，又避免用结果惩罚过去的自己。', '["后知之明偏见", "复盘", "自责", "决策", "不确定性", "预警信号"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 230, now()),
(100231, '双曲线折扣：拖延和冲动都在高估眼前、低估未来', '双曲线折扣描述了人更重视眼前收益、低估未来代价的倾向。它会让用户今天刷手机、明天补救；今天冲动消费、未来焦虑；今天逃避对话、未来关系更僵。App 可把长期目标改造成近端约束：提前设截止日期、把任务拆成今天能完成的最小动作、让未来代价现在可见、把承诺告诉可信的人。不要只靠意志力和未来的自己，未来的自己通常也会遇到同样的诱惑。', '["双曲线折扣", "拖延", "冲动", "未来自我", "承诺", "行动设计"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 231, now()),
(100232, '邓宁—克鲁格效应：越不熟练，越需要外部反馈校准', '人在能力不足时，常因为缺少判断标准而高估自己；能力提升后，反而更能看见复杂性和不足。App 可在学习、关系修复或自我成长问题中提醒：自信不等于熟练，挫败也不等于没天赋。更可靠的校准方式是外部反馈、可量化结果、刻意练习和复盘证据。用户若觉得“我已经很会沟通/我很懂自己”，可以追问：别人体验是否一致？有没有反复出现的失败模式？我是否请过可靠的人指出盲点？', '["邓宁克鲁格效应", "自我评估", "反馈", "刻意练习", "盲点", "学习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 232, now()),
(100233, '基本归因错误：先看情境压力，再判断人格问题', '基本归因错误让人解释他人行为时过度强调性格，低估情境压力；解释自己行为时却更容易强调处境。伴侣迟到不一定是不在乎，员工沉默不一定是没责任，孩子顶嘴也不一定是品格差。App 可在评价他人前加入情境检查：当时 TA 面临什么压力、信息、角色和资源限制？类似情境下别人会怎样？有没有稳定的跨场景模式？先看情境，不等于纵容伤害，而是让判断更准确，边界更有针对性。', '["基本归因错误", "情境", "人格判断", "关系冲突", "社会心理学", "非标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 233, now()),
(100234, '边际效用递减：同一种满足会越用越不灵', '戈森第一定律提醒，连续满足同一种享受时，新增快乐通常会递减。它可转译为生活建议：重复刷短视频、购物、甜食、被认可或工作成就，一开始有效，后来可能越来越麻木，还需要更高剂量。App 可帮助用户区分“我真的需要更多”还是“同一种满足已经递减”。恢复活力常需要多元满足：身体休息、关系连接、创造、学习、贡献和意义，而不是把所有情绪都压到同一个出口。', '["边际效用递减", "行为经济学", "享受", "成瘾风险", "生活平衡", "多元满足"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 234, now()),
(100235, '享受均等：时间和精力要分配给真正有价值的需要', '戈森第二定律强调，要让整体享受更大，不能把全部资源投入单一需要，而要在多种需要之间分配，直到继续投入的边际收益大致相当。App 可把它用于时间管理和身心平衡：工作、亲密、健康、学习、休息、意义都需要一定投入；某一项过度挤占其他项，短期可能看似高效，长期会造成失衡。用户做选择时可问：我继续把时间投在这里，新增收益还高吗？是否有另一个被忽视的需要，投入一点就能明显改善生活质量？', '["享受均等", "资源分配", "时间管理", "生活平衡", "需要", "行为经济学"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 235, now()),
(100236, '交换不是占便宜：稳定合作要让双方都看见收益', '交换关系能持续，不是因为一方永远赢，而是双方都认为交换后的处境比交换前更好。无论是亲密关系、家庭分工、团队协作还是商业谈判，如果长期只有一方付出、另一方享受，关系就会累积怨气。App 可把协商建议从“谁该听谁”改成“双方各自得到什么、付出什么、风险是什么、如何复盘”。好的交换不是冷冰冰算计，而是让贡献、需要和回报被看见，减少隐性账本和情绪爆发。', '["交换规律", "合作", "互惠", "关系协商", "家庭分工", "谈判"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v9-20260705', 236, now())
